    /* ===== src/core/tables.js ===== */
    /*
     * Decoded runtime tables (spec §7.8). Works in the browser and under node:
     * base64 is decoded by hand so no Buffer/atob difference matters.
     */



    const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

    function decodeBase64(text) {
        const clean = text.replace(/=+$/, '');
        const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
        let buf = 0;
        let bits = 0;
        let o = 0;
        for (let i = 0; i < clean.length; i++) {
            buf = (buf << 6) | B64.indexOf(clean[i]);
            bits += 6;
            if (bits >= 8) {
                bits -= 8;
                out[o++] = (buf >> bits) & 255;
            }
        }
        return out;
    }

    let cache = null;

    function tables() {
        if (cache) return cache;
        const eqBytes = decodeBase64(EQUITY169_B64);
        const equity = new Float32Array(169 * 169);
        for (let i = 0; i < equity.length; i++) equity[i] = (eqBytes[2 * i] | (eqBytes[2 * i + 1] << 8)) / 65535;
        const order = Array.from(decodeBase64(ORDER169_B64));
        /* Percentile (0..1) of each class's midpoint in the strongest-first order, by combos. */
        const percentile = new Float32Array(169);
        let acc = 0;
        for (const ci of order) {
            const n = CLASS_COMBO_COUNT[ci];
            percentile[ci] = (acc + n / 2) / 1326;
            acc += n;
        }
        cache = {
            manifest: TABLES_MANIFEST,
            equity,
            valid: decodeBase64(VALID169_B64),
            order,
            percentile,
            pushfold: PUSHFOLD_TABLE,
            priors: PRIORS_TABLE,
            likelihood: LIKELIHOOD_TABLE,
            foldcurve: FOLDCURVE_TABLE,
            tilt: TILT_TABLE,
            realization: REALIZATION_TABLE,
        };
        return cache;
    }

    /** Heads-up preflop equity of hero class vs villain class. */
    const classEquity = (hero, villain) => tables().equity[hero * 169 + villain];

    /* ===== src/core/model.js ===== */
    /*
     * Model switches. The simulator turns them on or off one at a time to measure each upgrade on the
     * same cards and opponents (sim/run.mjs ours-no<flag> / ours-with<flag>).
     *   foldCells  street and heads-up/multiway shifts of the fold curve: OFF. They are real in PHH, but
     *              the simulator gate failed them (-362 +/- 204 bb/100); waiting for Torn hands.
     * Added after the 2026-09-27 live session (docs/model-review-2026-09-27.md):
     *   raiserFold    a player who bet or raised this street folds at its own low rate; no +0.12; no size-curve
     *                 extrapolation past the largest bucket without 10 own observations
     *   evLowerBound  bets and raises are priced with a cautious fold rate, one standard error below the estimate
     *   multiway      every likely set of callers is priced, not one heads-up caller
     *   preflopSize   preflop re-raise folds depend on the size and on who already put money in
     *   raiseBack     a bet can be raised back; with little equity hero then folds
     *   commitRail    no all-in unless hero has 30% against the hands that continue (short stacks and all-ins aside)
     *   tableLayer    stats lean on this table's players before the pool
     *   raiseNarrow   a post-flop raise narrows the range with the parametric model, not the flat showdown fit
     * Added after the second live session (docs/live-session-2026-09-27.md, session 4 and the replay):
     *   valueRaise    a post-flop raise is value (top ~12% of hands on the board); own aggression moves it only after 30 actions
     *   warGuard      facing a raise war (a 3-bet or more preflop, a raise post-flop), no re-raise or all-in above 25 bb
     *                 without QQ+/AK preflop or a set or better post-flop
     *   tieCheaper    when a raise that commits over a quarter of the stack is within the noise of calling or folding,
     *                 advise the cheaper action
     */
    const DEFAULT_MODEL = Object.freeze({
        foldCurve: true, foldCells: false, sizeTell: true, fittedR: true, recency: true, tilt: true,
        raiserFold: true, evLowerBound: true, multiway: true, preflopSize: true, raiseBack: true, commitRail: true, tableLayer: true, raiseNarrow: true,
        valueRaise: true, warGuard: true, tieCheaper: true,
        potShare: true, classR: true, impliedOdds: true, callMix: true, sizeRaiseBack: true, fcold: true, bluffHU: true,
    });
    /*
     * Added from the edge research (reports/Torn poker edge sources.md, changes 2-8):
     *   potShare       realized pot shares add up: hero R*eq against the opponents' R*(1-eq), and R slides to 1 as the
     *                  stack-to-pot ratio falls, so a call and an all-in are priced on one scale (no fold-or-shove bias)
     *   classR         preflop realization by hand class: pairs and suited hands above, offsuit junk below
     *   impliedOdds    a pocket pair calling a raise deep (100 bb+, SPR 6+) is credited a share of the stack for the set
     *   callMix        a caller's range is part top slice, part whatever they came in with (Torn callers are weak)
     *   sizeRaiseBack  a post-flop bet is raised back more often the smaller it is (42% for a third of the pot)
     *   fcold          a player with no chips in the street folds to a raise at its own rate (Torn 65%)
     *   bluffHU        no post-flop bluff into two or more players
     */
    const MODEL = { ...DEFAULT_MODEL };

    function setModel(flags) {
        for (const k of Object.keys(MODEL)) if (k in flags) MODEL[k] = !!flags[k];
    }

    /* ===== src/core/util.js ===== */
    /* Small shared helpers. The bundler flattens scope, so helpers live here once. */
    const clamp = (x, lo, hi) => Math.min(hi, Math.max(lo, x));
    const sig = (x) => 1 / (1 + Math.exp(-x));
    const pct = (x, d = 0) => (x * 100).toFixed(d) + '%';

    /* ===== src/core/ranges.js ===== */
    /*
     * Opponent ranges as 1,326 combo weights (spec §7.5).
     *
     * Preflop: a soft band of the strongest-first hand order (tables.order),
     * sized from the player's shrunk stats. Postflop: each action multiplies
     * the weights by a likelihood of that action given the combo's strength on
     * this board. v1 uses a parametric likelihood; the LAB replaces it with
     * fitted tables once there are enough showdowns.
     *
     * Draws are credited as medium strength (a flush or open-ended draw is
     * treated as at least the 55th percentile), which is crude but better than
     * treating them as air.
     */







    const newRange = (fill = 1) => new Float32Array(1326).fill(fill);

    /** Weight 1 for classes whose strength percentile lies in [lo, hi], with soft edges. */
    function bandRange(lo, hi, soft = 0.025) {
        const pct = tables().percentile;
        const out = new Float32Array(1326);
        for (let k = 0; k < 1326; k++) {
            const p = pct[COMBO_CLASS[k]];
            const inLo = lo <= 0 ? 1 : sig((p - lo) / soft);
            const inHi = hi >= 1 ? 1 : 1 - sig((p - hi) / soft);
            out[k] = inLo * inHi;
        }
        return out;
    }

    const topRange = (fraction, soft) => bandRange(0, clamp(fraction, 0.003, 1), soft);

    function mixRanges(a, b, wa, wb) {
        const out = new Float32Array(1326);
        for (let k = 0; k < 1326; k++) out[k] = wa * a[k] + wb * b[k];
        return out;
    }

    /**
     * The preflop range of a player after their preflop action.
     * rate(key) returns the player's shrunk stat (stats.js/priors.js).
     */
    function preflopRange(action, rate, { depthKey = 'd4' } = {}) {
        const vpip = clamp(rate('vpip'), 0.05, 0.98);
        const pfr = clamp(rate('pfr'), 0.02, vpip);
        switch (action) {
            case 'open':
                return topRange(clamp(rate('rfi') > 0 ? Math.max(rate('rfi'), pfr) : pfr * 1.3, 0.03, 0.9));
            case 'threebet':
                return topRange(clamp(rate('threebet'), 0.02, 0.4));
            case 'fourbet':
                return topRange(0.035);
            case 'shove':
                return topRange(clamp(rate('shove.' + depthKey) * 2.5, 0.02, 1));
            case 'flat': {
                /* Calls a raise: mostly the band below their 3-bet range, plus some trapped monsters. */
                const hi = clamp(vpip * 0.85, 0.08, 0.95);
                return mixRanges(bandRange(clamp(rate('threebet'), 0.02, 0.2), hi), topRange(0.04), 1, 0.3);
            }
            case 'limp':
                return mixRanges(bandRange(pfr * 0.6, vpip), topRange(pfr * 0.6), 1, 0.25);
            case 'check':
                return mixRanges(newRange(1), topRange(pfr), 1, -0.7);
            default:
                return newRange(1);
        }
    }

    /* ---- postflop ---- */

    function hasDraw(a, b, board) {
        const cards = [a, b, ...board];
        const suits = [0, 0, 0, 0];
        let mask = 0;
        for (const c of cards) {
            suits[c & 3]++;
            mask |= 1 << (c >> 2);
        }
        if (board.length < 5 && suits.some((n) => n === 4)) return true;
        if (board.length >= 5) return false;
        const m = mask | ((mask >> 12) & 1);
        for (let lo = 0; lo <= 8; lo++) if (((m >> lo) & 15) === 15) return true;
        return false;
    }

    /** Strength percentile (0 = weakest, 1 = strongest) of each live combo within the range, on this board. */
    function strengthPercentiles(weights, board, dead = []) {
        const used = new Uint8Array(52);
        for (const c of board) used[c] = 1;
        for (const c of dead) used[c] = 1;
        const items = [];
        const cards = new Array(2 + board.length);
        for (let i = 0; i < board.length; i++) cards[2 + i] = board[i];
        for (let k = 0; k < 1326; k++) {
            if (weights[k] <= 0 || used[COMBO_A[k]] || used[COMBO_B[k]]) continue;
            cards[0] = COMBO_A[k];
            cards[1] = COMBO_B[k];
            items.push([k, evaluate(cards, cards.length)]);
        }
        items.sort((x, y) => x[1] - y[1]);
        let total = 0;
        for (const [k] of items) total += weights[k];
        const out = new Float32Array(1326);
        let acc = 0;
        for (let i = 0; i < items.length; ) {
            let j = i;
            let w = 0;
            while (j < items.length && items[j][1] === items[i][1]) w += weights[items[j++][0]];
            const mid = total > 0 ? (acc + w / 2) / total : 0.5;
            for (let t = i; t < j; t++) {
                const k = items[t][0];
                out[k] = hasDraw(COMBO_A[k], COMBO_B[k], board) ? Math.max(mid, 0.55) : mid;
            }
            acc += w;
            i = j;
        }
        return out;
    }

    function sizeShare(tell, size, s) {
        const j = size <= tell.edges[0] ? 0 : size <= tell.edges[1] ? 1 : size <= tell.edges[2] ? 2 : 3;
        let den = 0;
        for (let i = 0; i < 4; i++) den += Math.exp(tell.a[i] + tell.g[i] * s);
        return Math.exp(tell.a[j] + tell.g[j] * s) / den;
    }

    /**
     * Multiply a range by the likelihood of a postflop action.
     * ctx: { sizeFrac (bet / pot before it), afq (0..1), foldRate (0..1, to this size) }
     */
    function applyPostflopAction(weights, board, dead, action, ctx = {}) {
        const fitted = tables().likelihood;
        /* The fitted table measures strength against every live combo, so use that scale with it. */
        const s = strengthPercentiles(fitted ? newRange(1) : weights, board, dead);
        const afq = clamp(ctx.afq ?? 0.3, 0, 1);
        const size = clamp(ctx.sizeFrac ?? 0.6, 0.1, 3);
        const out = new Float32Array(1326);
        const poolAfq = tables().priors.stats.afq ? tables().priors.stats.afq.mean : 0.3;
        for (let k = 0; k < 1326; k++) {
            const w = weights[k];
            if (w <= 0) continue;
            const x = s[k];
            let like;
            /* The showdown fit barely narrows a raise (floor 0.114 over 98% of hands; review 2026-09-27): raises use the parametric model. */
            if (action === 'raise' && MODEL.valueRaise) {
                /*
                 * Torn raises are value: 12 of 14 at showdown were two pair or better, none were air (live 2026-09-27,
                 * docs/table-tendencies-2026-09-27.md). Roughly the top 12% of hands on the board plus a small floor.
                 * A player's own aggression moves it only once it rests on 30+ post-flop actions.
                 */
                const rel = (ctx.afqN ?? 0) >= 30 ? afq - poolAfq : 0;
                const t = clamp(0.88 + 0.05 * (size - 0.6) - 0.25 * rel, 0.75, 0.96);
                /* The floor scales with the value part, so a bigger raise stays the stronger range. */
                const floor = clamp(((0.03 + 0.1 * rel) * (1 - t)) / 0.12, 0.01, 0.08);
                like = floor + (1 - floor) * sig((x - t) / 0.04);
            } else if (fitted && (action === 'bet' || (action === 'raise' && !MODEL.raiseNarrow))) {
                /* LAB fit (showdown hands); a player more aggressive than the pool bets lighter. */
                const p = action === 'raise' ? fitted.raise : fitted.bet;
                const tell = action === 'bet' && MODEL.sizeTell ? fitted.betSize : null;
                const t = clamp(p.t - 0.3 * (afq - poolAfq) + (MODEL.sizeTell ? 0 : 0.05 * (size - 0.6)), 0.3, 1.05);
                like = p.b + (1 - p.b) * sig((x - t) / p.w);
                /* Which size a bettor picks, by strength (lab sizetell): P(bucket | s). None for raises: no tell there. */
                if (tell) like *= sizeShare(tell, size, x);
            } else if (action === 'bet' || action === 'raise') {
                const t = clamp(1 - (0.25 + 0.6 * afq) + 0.1 * (size - 0.6) + (action === 'raise' ? 0.15 : 0), 0.3, 0.95);
                const bluff = (0.04 + 0.2 * afq) * (action === 'raise' ? 0.6 : 1);
                like = bluff + (1 - bluff) * sig((x - t) / 0.08);
            } else if (action === 'call') {
                const fr = clamp(ctx.foldRate ?? 0.4, 0.05, 0.9);
                like = 0.05 + 0.95 * sig((x - fr) / 0.1);
                /* Torn callers are weaker than a clean top slice (18/22 shown callers of a bet had less than top pair). */
                if (MODEL.callMix) {
                    const m = tables().priors.stats.callmix?.mean ?? 0.4;
                    like = (1 - m) * like + m * (1 - fr);
                }
            } else if (action === 'check') {
                const t = clamp(1 - (0.25 + 0.6 * afq), 0.3, 0.95);
                like = 1 - (0.3 + afq) * 0.7 * sig((x - t) / 0.08);
            } else {
                like = 1;
            }
            out[k] = w * like;
        }
        return out;
    }

    /** Keep the strongest (1 - foldFraction) of a range by strength: the part that continues. */
    function continuingRange(weights, board, dead, foldFraction, mix = 0) {
        const f = clamp(foldFraction, 0, 0.98);
        if (f <= 0) return weights;
        const s = board.length ? strengthPercentiles(weights, board, dead) : tables().percentile;
        const out = new Float32Array(1326);
        /* mix: the share of callers who are not the top slice (weights stay relative, so (1 - f) keeps the two parts in proportion). */
        const m = clamp(mix, 0, 0.9);
        for (let k = 0; k < 1326; k++) {
            if (weights[k] <= 0) continue;
            const x = board.length ? s[k] : 1 - s[COMBO_CLASS[k]];
            out[k] = weights[k] * ((1 - m) * sig((x - f) / 0.05) + m * (1 - f));
        }
        return out;
    }

    /** Share of live combos the range holds, and its strongest classes, for display. */
    function rangeSummary(weights, dead = []) {
        const used = new Uint8Array(52);
        for (const c of dead) used[c] = 1;
        let sum = 0;
        let live = 0;
        const byClass = new Float32Array(169);
        const countClass = new Float32Array(169);
        for (let k = 0; k < 1326; k++) {
            if (used[COMBO_A[k]] || used[COMBO_B[k]]) continue;
            live++;
            sum += weights[k];
            byClass[COMBO_CLASS[k]] += weights[k];
            countClass[COMBO_CLASS[k]]++;
        }
        /* Classes the range holds most of, heaviest first (after a flop bet that is made hands, not preflop order). */
        const classes = [];
        const avg = [];
        for (let ci = 0; ci < 169; ci++) if (countClass[ci]) avg.push([ci, byClass[ci] / countClass[ci]]);
        const top = Math.max(0, ...avg.map((x) => x[1]));
        avg.sort((x, y) => y[1] - x[1] || tables().percentile[x[0]] - tables().percentile[y[0]]);
        for (const [ci, w] of avg) if (w >= 0.5 * top && w > 0.05) classes.push(CLASS_NAMES[ci]);
        return { fraction: live ? sum / live : 0, classes, text: classes.slice(0, 14).join(', ') + (classes.length > 14 ? '…' : '') };
    }

    /* ===== src/core/stats.js ===== */
    /*
     * Opponent stats, counted PER OPPORTUNITY (spec §7.2, L4). This file is the
     * single definition: the userscript, the simulator and the LAB (through
     * tools/stats-from-hands.mjs) all count with it.
     *
     * Each stat is [opportunities, made]. Keys:
     *   vpip pfr limp rfi rfi.<EP|MP|CO|BTN|SB> threebet f3b
     *   fvo.<s1-s4>   fold vs an open, by open size (<=2.5, <=4, <=8, >8 bb)
     *   fiso.<s1-s4>  a limper folding to a raise, by raise size
     *   shove.<d1-d4> preflop all-in per decision, by depth (<=10, <=20, <=40, >40 bb)
     *   cbet.<street> fcb.<street>[.<b1-b4>][.hu|.mw] fbet.<b1-b4> donk xr afq wtsd wsd
     *   fraise        post-flop: a player who bet or raised this street folding when raised
     *   fcold         post-flop: a player with no chips in this street folding to a raise
     *   (b1-b4: bet size vs the pot before it, <=0.4, <=0.7, <=1.1, >1.1)
     */



    const STREETS = ['flop', 'turn', 'river'];

    const preBucket = (bbs) => (bbs <= 2.5 ? 's1' : bbs <= 4 ? 's2' : bbs <= 8 ? 's3' : 's4');
    const depthBucket = (bbs) => (bbs <= 10 ? 'd1' : bbs <= 20 ? 'd2' : bbs <= 40 ? 'd3' : 'd4');
    const betBucket = (f) => (f <= 0.4 ? 'b1' : f <= 0.7 ? 'b2' : f <= 1.1 ? 'b3' : 'b4');

    /**
     * Which recency/tilt family a stat follows (lab/tilt.py measured one per family), and the sign of
     * a tilt offset for it: a looser player folds less, so fold-type stats take the offset negated.
     */
    function familyOf(key) {
        const k = key.split('.')[0];
        if (k === 'vpip' || k === 'limp') return { fam: 'pre', sign: 1 };
        if (k === 'fvo' || k === 'fiso' || k === 'f3b') return { fam: 'pre', sign: -1 };
        if (k === 'pfr' || k === 'rfi' || k === 'threebet') return { fam: 'raise', sign: 1 };
        if (k === 'shove') return { fam: 'shove', sign: 1 };
        if (k === 'afq' || k === 'cbet' || k === 'donk' || k === 'xr') return { fam: 'postAgg', sign: 1 };
        if (k === 'fbet' || k === 'fcb') return { fam: 'postFold', sign: 1 };
        if (k === 'wtsd') return { fam: 'postFold', sign: -1 };
        return null;
    }

    const playerKey = (seat) => (seat.xid ? String(seat.xid) : 'name:' + seat.name);

    function bump(map, key, made) {
        const c = map[key] || (map[key] = [0, 0]);
        c[0]++;
        if (made) c[1]++;
    }

    /** Counters contributed by one HandRecord: { playerKey: { stat: [opp, made] } }. */
    function statsFromHand(rec) {
        const out = Object.create(null);
        const bb = rec.table?.bb || 0;
        const seatByName = new Map(rec.seats.map((s) => [s.name, s]));
        const keyOf = (name) => playerKey(seatByName.get(name) || { name });
        const S = (name) => out[keyOf(name)] || (out[keyOf(name)] = Object.create(null));

        const pre = rec.actions.filter((a) => a.street === 'preflop');
        const firstPre = new Map();
        const limped = new Set();
        let opener = null;
        const facedOpen = new Set();
        for (const a of pre) {
            const st = S(a.who);
            const pos = seatByName.get(a.who)?.position || null;
            if (!firstPre.has(a.who)) {
                firstPre.set(a.who, a);
                if (a.preflopRaises === 0 && pos !== 'BB') {
                    bump(st, 'limp', a.type === 'call');
                    if (a.limpers === 0) {
                        bump(st, 'rfi', a.type === 'raise' || a.type === 'bet');
                        const g = pos && POSITION_GROUP[pos];
                        if (g && g !== 'BB') bump(st, 'rfi.' + g, a.type === 'raise' || a.type === 'bet');
                    }
                }
                if (bb > 0 && a.stackBefore !== null && a.stackBefore !== undefined) {
                    bump(st, 'shove.' + depthBucket((a.stackBefore + a.toAmount - a.added) / bb), a.allin && (a.type === 'raise' || a.type === 'bet'));
                }
            }
            if (a.preflopRaises === 0 && a.type === 'call') limped.add(a.who);
            if (a.preflopRaises === 1 && a.who !== opener && !facedOpen.has(a.who)) {
                facedOpen.add(a.who);
                bump(st, 'threebet', a.type === 'raise');
                if (bb > 0) {
                    const size = preBucket(a.currentBet / bb);
                    if (limped.has(a.who)) bump(st, 'fiso.' + size, a.type === 'fold');
                    else bump(st, 'fvo.' + size, a.type === 'fold');
                }
            }
            if (a.preflopRaises === 2 && a.who === opener && !st._f3b) {
                st._f3b = true;
                bump(st, 'f3b', a.type === 'fold');
            }
            if ((a.type === 'raise' || a.type === 'bet') && a.preflopRaises === 0) opener = a.who;
        }
        for (const [name] of firstPre) {
            const mine = pre.filter((a) => a.who === name);
            const st = S(name);
            bump(st, 'vpip', mine.some((a) => a.type === 'call' || a.type === 'raise' || a.type === 'bet'));
            bump(st, 'pfr', mine.some((a) => a.type === 'raise' || a.type === 'bet'));
            st._hand = 1;
        }

        for (const street of STREETS) {
            const acts = rec.actions.filter((a) => a.street === street);
            if (!acts.length) continue;
            let bets = 0;
            let raised = false;
            const acted = new Set();
            const checked = new Set();
            const aggressive = new Set();
            const put = new Set();
            const agg = acts[0].prevAggressor;
            for (const a of acts) {
                const st = S(a.who);
                const first = !acted.has(a.who);
                if (aggressive.has(a.who) && a.facing > 0) bump(st, 'fraise', a.type === 'fold');
                /* Facing a raise with no chips in this street yet ("cold"). */
                if (raised && !put.has(a.who) && a.facing > 0) bump(st, 'fcold', a.type === 'fold');
                if (first && bets === 0) {
                    if (a.who === agg) bump(st, 'cbet.' + street, a.type === 'bet');
                    else if (agg && !acted.has(agg) && rec.seats.some((s) => s.name === agg)) bump(st, 'donk.' + street, a.type === 'bet');
                }
                if (bets === 1 && !raised && a.facing > 0) {
                    const b = a.facingFrac !== null && a.facingFrac !== undefined ? betBucket(a.facingFrac) : null;
                    const lastBettor = [...acts.slice(0, acts.indexOf(a))].reverse().find((x) => x.type === 'bet');
                    if (lastBettor && lastBettor.who === agg) {
                        const hu = a.live <= 2 ? 'hu' : 'mw';
                        bump(st, 'fcb.' + street, a.type === 'fold');
                        if (b) bump(st, `fcb.${street}.${b}`, a.type === 'fold');
                        bump(st, `fcb.${street}.${hu}`, a.type === 'fold');
                    }
                    if (b) bump(st, 'fbet.' + b, a.type === 'fold');
                    if (checked.has(a.who)) bump(st, 'xr.' + street, a.type === 'raise');
                }
                /* Folds count (the HUD definition): without them a check-fold player who bets only real hands read as a
                   "Maniac" and their raises as wide (live 2026-09-27, 56e22a25: 73% without folds, 44% with). */
                if (a.type === 'bet' || a.type === 'raise' || a.type === 'call' || a.type === 'fold') bump(st, 'afq', a.type === 'bet' || a.type === 'raise');
                if (a.type === 'bet') bets++;
                if (a.type === 'raise') raised = true;
                if (a.type === 'bet' || a.type === 'raise') aggressive.add(a.who);
                if (a.type === 'bet' || a.type === 'raise' || a.type === 'call') put.add(a.who);
                if (a.type === 'check') checked.add(a.who);
                acted.add(a.who);
            }
        }

        const folded = new Set(rec.actions.filter((a) => a.type === 'fold').map((a) => a.who));
        const live = rec.seats.filter((s) => !folded.has(s.name) && firstPre.has(s.name));
        const showdown = live.length > 1 && rec.board.length === 5;
        const winners = new Set((rec.winners || []).map((w) => w.who));
        for (const s of rec.seats) {
            if (!s.sawFlop) continue;
            const st = S(s.name);
            const went = showdown && !folded.has(s.name);
            bump(st, 'wtsd', went);
            if (went) bump(st, 'wsd', winners.has(s.name));
        }
        for (const k of Object.keys(out)) {
            delete out[k]._f3b;
        }
        return out;
    }

    const recency = () => (tables().tilt ? tables().tilt.recency : null);

    /** Session net and the last big loss, in big blinds (the states lab/tilt.py tested). */
    function trackState(p, rec, name, bb) {
        const t = tables().tilt;
        const net = rec.net && rec.net[name];
        if (!t || !bb || net === undefined || net === null) return;
        const netBB = net / bb;
        const gap = t.states.sessionDown.gapMin * 60e3;
        if (!p.sess || (rec.t0 && p.lastSeen && rec.t0 - p.lastSeen > gap)) p.sess = { net: 0, hands: 0 };
        p.sess.net += netBB;
        p.sess.hands++;
        if (netBB <= -t.states.bigLoss.lossBB) p.bigLoss = { at: p.hands, bb: Math.round(-netBB) };
    }

    /** Merge one hand into a per-player store: { key: { hands, stats: {...}, name, xid, lastSeen, stakes: {bb: n} } }. */
    function accumulate(store, rec) {
        const add = statsFromHand(rec);
        const bb = rec.table?.bb || 0;
        for (const s of rec.seats) {
            const key = playerKey(s);
            const inc = add[key];
            if (!inc) continue;
            const p = store[key] || (store[key] = { key, name: s.name, xid: s.xid ?? null, hands: 0, stats: {}, lastSeen: 0, stakes: {}, shown: [] });
            p.name = s.name;
            if (inc._hand) p.hands++;
            trackState(p, rec, s.name, bb);
            p.lastSeen = Math.max(p.lastSeen, rec.t1 || 0);
            if (bb) p.stakes[bb] = (p.stakes[bb] || 0) + 1;
            const rc = recency();
            for (const [k, v] of Object.entries(inc)) {
                if (k.startsWith('_')) continue;
                const c = p.stats[k] || (p.stats[k] = [0, 0]);
                c[0] += v[0];
                c[1] += v[1];
                const fam = rc && familyOf(k);
                if (fam && rc[fam.fam]) {
                    /* Decayed [opportunities, made, at hand #], decayed lazily by the player's hands since. */
                    const recent = p.recent || (p.recent = {});
                    const e = recent[k] || [0, 0, p.hands];
                    const f = 0.5 ** ((p.hands - e[2]) / rc[fam.fam].halfLife);
                    recent[k] = [e[0] * f + v[0], e[1] * f + v[1], p.hands];
                }
            }
            const cards = rec.shown && rec.shown[s.name];
            if (cards) {
                const line = rec.actions.filter((a) => a.who === s.name && a.type !== 'check').map((a) => a.street[0] + ':' + a.type[0]).join(' ');
                p.shown.push({ c: cards, line, t: rec.t1 || 0 });
                if (p.shown.length > 60) p.shown.shift();
            }
        }
        return store;
    }

    /* ===== src/core/priors.js ===== */
    /*
     * Shrunk rates (spec §7.4, L5). A player's rate for a stat is
     *   (made + k * prior) / (opportunities + k)
     * where the prior is the pool mean for that stat, or, for a fine-grained key
     * such as fcb.flop.b2 with no pool entry, the player's own shrunk rate for
     * the parent key (fcb.flop, then fcb). So thin specific samples lean on the
     * player's broader tendency before they lean on the pool.
     */




    const DEFAULT_K = 15;

    function poolEntry(key, stakeBB) {
        const pri = tables().priors;
        const byStake = pri.byStake && pri.byStake[key] && stakeBB ? pri.byStake[key][String(stakeBB)] : null;
        const base = pri.stats[key];
        if (!base && !byStake) return null;
        return { mean: byStake ? byStake.mean : base.mean, k: base ? base.k : DEFAULT_K, source: byStake ? byStake.source : base.source };
    }

    const parentOf = (key) => (key.includes('.') ? key.slice(0, key.lastIndexOf('.')) : null);

    /*
     * Table layer (2026-09-27 live session: the pool prior assumed far more folding than the Torn tables showed).
     * A player's rate leans first on the other players seated at this table, then on the pool, so a table
     * that calls everything is learned within an orbit or two instead of one player at a time.
     */
    let tablePlayers = null;
    function setTable(stores) {
        tablePlayers = stores && stores.length ? stores.filter(Boolean) : null;
    }

    function tableMean(key, mean, k, player) {
        if (!MODEL.tableLayer || !tablePlayers) return mean;
        let n = 0;
        let made = 0;
        for (const st of tablePlayers) {
            const c = st !== player && st.stats && st.stats[key];
            if (c) {
                n += c[0];
                made += c[1];
            }
        }
        return (made + 2 * k * mean) / (n + 2 * k);
    }

    /**
     * @param {{ stats?: object } | null} player  a store entry from stats.accumulate (or null for "unknown player")
     * @returns {{ rate: number, n: number, source: string }}
     */
    function shrunk(player, key, stakeBB = 0) {
        const counts = (player && player.stats && player.stats[key]) || [0, 0];
        const pool = poolEntry(key, stakeBB);
        let mean;
        let k;
        let source;
        if (pool) {
            ({ mean, k, source } = pool);
            mean = tableMean(key, mean, k, player);
        } else {
            const parent = parentOf(key);
            if (!parent) return { rate: 0.5, n: counts[0], source: 'none', life: 0.5, base: 0.5, k: DEFAULT_K };
            /* The parent's recent form, not its tilt shift: the shift is applied once, below. */
            mean = shrunk(player, parent, stakeBB).base;
            k = DEFAULT_K;
            source = 'parent';
        }
        const life = (counts[1] + k * mean) / (counts[0] + k);
        const base = MODEL.recency ? recentRate(player, key, life) : life;
        const rate = MODEL.tilt ? tiltShift(player, key, base) : base;
        return { rate, n: counts[0], source, life, base, k };
    }

    /*
     * Recent form (lab/tilt.py, IRC held-out players): decayed counts shrunk to the player's own
     * lifetime rate. It beat lifetime-only stats on every target; preflop the gain was largest.
     */
    function decayed(player, key) {
        const t = tables().tilt;
        const e = player && player.recent && player.recent[key];
        const fam = familyOf(key);
        if (!t || !e || !fam || !t.recency[fam.fam]) return null;
        const r = t.recency[fam.fam];
        const f = 0.5 ** ((player.hands - e[2]) / r.halfLife);
        return { n: e[0] * f, made: e[1] * f, m: r.m };
    }

    function recentRate(player, key, life) {
        const d = decayed(player, key);
        return d ? (d.made + d.m * life) / (d.n + d.m) : life;
    }

    /** Which measured states hold for this player before the current hand. */
    function tiltStates(player) {
        const t = tables().tilt;
        const out = [];
        if (!t || !player) return out;
        if (player.bigLoss && player.hands - player.bigLoss.at + 1 <= t.states.bigLoss.hands) out.push('bigLoss');
        if (player.sess && player.sess.net <= t.states.sessionDown.netBB) out.push('sessionDown');
        return out;
    }

    function tiltShift(player, key, rate) {
        const t = tables().tilt;
        const fam = familyOf(key);
        if (!t || !fam) return rate;
        let z = 0;
        for (const st of tiltStates(player)) {
            const off = t.offsets[st] && t.offsets[st][fam.fam];
            if (off) z += fam.sign * off.beta;
        }
        if (!z) return rate;
        const r = Math.min(1 - 1e-4, Math.max(1e-4, rate));
        return 1 / (1 + Math.exp(-(Math.log(r / (1 - r)) + z)));
    }

    /**
     * A tile note only when recent form is 2+ standard errors from the player's lifetime rate
     * (lab/tilt.py: WWpokerHUD's +20-point rule fired on 12% of IRC hands and most of its gap was noise).
     */
    function formChange(player, key = 'vpip', stakeBB = 0) {
        if (!player || player.hands < 30) return null;
        const d = decayed(player, key);
        if (!d || d.n < 8) return null;
        const { life } = shrunk(player, key, stakeBB);
        const recent = d.made / d.n;
        const se = Math.sqrt(Math.max(1e-4, life * (1 - life)) / d.n);
        if (Math.abs(recent - life) <= 2 * se) return null;
        const lossRecent = player.bigLoss && player.hands - player.bigLoss.at < 30 ? player.bigLoss.bb : null;
        return { key, recent, life, n: Math.round(d.n), dir: recent > life ? 'up' : 'down', lossBB: lossRecent };
    }

    const rateOf = (player, stakeBB = 0) => (key) => shrunk(player, key, stakeBB).rate;

    /** Player type for the seat tile. Returns { type, label, provisional }. */
    function archetype(player, stakeBB = 0) {
        const r = rateOf(player, stakeBB);
        const vpip = r('vpip');
        const pfr = r('pfr');
        const afq = r('afq');
        const hands = player ? player.hands : 0;
        const ratio = vpip > 0 ? pfr / vpip : 0;
        let type;
        if (hands < 5) type = 'new';
        /* Post-flop aggression alone never makes a maniac: on Torn it marked limp-everything players whose raises were value (live 2026-09-27). */
        else if (vpip >= 0.45 && (pfr >= 0.25 || (afq >= 0.55 && pfr >= 0.15))) type = 'maniac';
        else if (vpip >= 0.45 && ratio < 0.25 && afq < 0.35) type = 'station';
        else if (vpip >= 0.32 && ratio < 0.45) type = 'fish';
        else if (vpip >= 0.28 && ratio >= 0.45) type = 'lag';
        else if (vpip < 0.18 && ratio < 0.55) type = 'nit';
        else if (vpip < 0.30 && ratio >= 0.5) type = 'tag';
        else type = 'reg';
        const LABEL = { new: 'New', maniac: 'Maniac', station: 'Station', fish: 'Fish', lag: 'LAG', nit: 'Nit', tag: 'TAG', reg: 'Reg' };
        const provisional = type !== 'new' && hands < 25;
        return { type, label: LABEL[type] + (provisional ? '?' : ''), provisional, hands, vpip, pfr, afq };
    }

    /** How sure a read is, 0..1, from the opportunities behind it. */
    const confidenceOf = (n, k = DEFAULT_K) => n / (n + 3 * k);

    /* ===== src/core/equity.js ===== */
    /*
     * Hero equity against one or more weighted ranges (spec §7.6).
     *
     *   preflop, heads-up   169x169 lookup; card removal at the combo level
     *   turn/river, HU      exact enumeration over the weighted range
     *   otherwise           Monte Carlo. Opponent hands are drawn FIRST (whole
     *                       tuple re-drawn on a card clash), then the runout,
     *                       so the joint distribution is right. An n-way split
     *                       pays 1/n. WWpokerHUD dealt the board first, which
     *                       over-weights boards that block narrow ranges.
     *
     * A range is a Float32Array(1326) of weights (see ranges.js).
     * Jobs can run in slices so the page never janks.
     */




    function liveCombos(weights, used) {
        const idx = [];
        const cum = [];
        let total = 0;
        for (let k = 0; k < 1326; k++) {
            const w = weights[k];
            if (w > 0 && !used[COMBO_A[k]] && !used[COMBO_B[k]]) {
                total += w;
                idx.push(k);
                cum.push(total);
            }
        }
        return { idx: Int16Array.from(idx), cum: Float64Array.from(cum), total };
    }

    function pick(live, r) {
        const target = r * live.total;
        let lo = 0;
        let hi = live.cum.length - 1;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (live.cum[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return live.idx[lo];
    }

    /** Heads-up preflop equity from the table. Weights over blocked combos are ignored. */
    function preflopEquityHU(hero, weights) {
        const hc = classOfCards(hero[0], hero[1]);
        let num = 0;
        let den = 0;
        for (let k = 0; k < 1326; k++) {
            const w = weights[k];
            if (w <= 0) continue;
            const a = COMBO_A[k];
            const b = COMBO_B[k];
            if (a === hero[0] || a === hero[1] || b === hero[0] || b === hero[1]) continue;
            num += w * classEquity(hc, COMBO_CLASS[k]);
            den += w;
        }
        return { eq: den > 0 ? num / den : 0.5, se: 0, n: 0, method: 'table', empty: den === 0 };
    }

    /** Exact heads-up equity with 4 or 5 board cards. */
    function exactHeadsUp(hero, board, weights) {
        const used = new Uint8Array(52);
        for (const c of hero) used[c] = 1;
        for (const c of board) used[c] = 1;
        const cards = new Array(7);
        const villain = new Array(7);
        let num = 0;
        let den = 0;
        const river = board.length === 5;
        for (let k = 0; k < 1326; k++) {
            const w = weights[k];
            const a = COMBO_A[k];
            const b = COMBO_B[k];
            if (w <= 0 || used[a] || used[b]) continue;
            if (river) {
                const h = evaluate([...hero, ...board]);
                const v = evaluate([a, b, ...board]);
                num += w * (h > v ? 1 : h === v ? 0.5 : 0);
                den += w;
                continue;
            }
            for (let i = 0; i < 4; i++) cards[2 + i] = villain[2 + i] = board[i];
            cards[0] = hero[0];
            cards[1] = hero[1];
            villain[0] = a;
            villain[1] = b;
            let share = 0;
            let n = 0;
            for (let r = 0; r < 52; r++) {
                if (used[r] || r === a || r === b) continue;
                cards[6] = villain[6] = r;
                const h = evaluate(cards);
                const v = evaluate(villain);
                share += h > v ? 1 : h === v ? 0.5 : 0;
                n++;
            }
            num += (w * share) / n;
            den += w;
        }
        return { eq: den > 0 ? num / den : 0.5, se: 0, n: 0, method: 'exact', empty: den === 0 };
    }

    /** A resumable Monte Carlo job. */
    function makeEquityJob({ hero, board = [], ranges, samples = 10000, seed = 1 }) {
        const used = new Uint8Array(52);
        for (const c of hero) used[c] = 1;
        for (const c of board) used[c] = 1;
        const lives = ranges.map((w) => {
            const live = liveCombos(w, used);
            if (live.total > 0) return live;
            const all = new Float32Array(1326).fill(1);
            return { ...liveCombos(all, used), fallback: true };
        });
        return {
            hero, board, lives, samples, rng: makeRng(seed), used,
            done: 0, share: 0, share2: 0, skipped: 0,
            oppCards: new Int8Array(ranges.length * 2),
            heroCards: new Array(7), oppHand: new Array(7), deck: new Int8Array(52),
            fallback: lives.some((l) => l.fallback),
        };
    }

    function stepEquityJob(job, budget) {
        const { hero, board, lives, rng, used, oppCards, heroCards, oppHand, deck } = job;
        const nOpp = lives.length;
        const need = 5 - board.length;
        const end = Math.min(job.samples, job.done + budget);
        heroCards[0] = hero[0];
        heroCards[1] = hero[1];
        for (let i = 0; i < board.length; i++) heroCards[2 + i] = board[i];
        const clash = new Uint8Array(52);
        while (job.done < end) {
            let ok = false;
            for (let tries = 0; tries < 60 && !ok; tries++) {
                ok = true;
                for (let o = 0; o < nOpp; o++) {
                    const k = pick(lives[o], rng());
                    const a = COMBO_A[k];
                    const b = COMBO_B[k];
                    if (clash[a] || clash[b]) {
                        ok = false;
                        break;
                    }
                    clash[a] = clash[b] = 1;
                    oppCards[2 * o] = a;
                    oppCards[2 * o + 1] = b;
                }
                if (!ok) clash.fill(0);
            }
            if (!ok) {
                job.skipped++;
                job.done++;
                continue;
            }
            let n = 0;
            for (let c = 0; c < 52; c++) if (!used[c] && !clash[c]) deck[n++] = c;
            for (let i = 0; i < need; i++) {
                const j = i + Math.floor(rng() * (n - i));
                const t = deck[i];
                deck[i] = deck[j];
                deck[j] = t;
                heroCards[2 + board.length + i] = deck[i];
            }
            const hs = evaluate(heroCards, 7);
            let best = -1;
            let ties = 0;
            for (let o = 0; o < nOpp; o++) {
                oppHand[0] = oppCards[2 * o];
                oppHand[1] = oppCards[2 * o + 1];
                for (let i = 2; i < 7; i++) oppHand[i] = heroCards[i];
                const s = evaluate(oppHand, 7);
                if (s > best) {
                    best = s;
                    ties = 0;
                }
                if (s === best) ties++;
            }
            const x = hs > best ? 1 : hs === best ? 1 / (ties + 1) : 0;
            job.share += x;
            job.share2 += x * x;
            clash.fill(0);
            job.done++;
        }
        return job.done >= job.samples;
    }

    function jobResult(job) {
        const n = job.done - job.skipped;
        if (n <= 0) return { eq: 0.5, se: 0.5, n: 0, method: 'monte-carlo', fallback: job.fallback };
        const mean = job.share / n;
        const variance = Math.max(0, job.share2 / n - mean * mean);
        return { eq: mean, se: Math.sqrt(variance / n), n, method: 'monte-carlo', skipped: job.skipped, fallback: job.fallback };
    }

    /** Pick the best method and run it to completion (node, sim and tests). */
    function computeEquity({ hero, board = [], ranges, samples = 10000, seed = 1 }) {
        if (ranges.length === 1 && board.length === 0) return preflopEquityHU(hero, ranges[0]);
        if (ranges.length === 1 && board.length >= 4) return exactHeadsUp(hero, board, ranges[0]);
        const job = makeEquityJob({ hero, board, ranges, samples, seed });
        stepEquityJob(job, samples);
        return jobResult(job);
    }

    /* ===== src/core/decision.js ===== */
    /*
     * Decision engine (spec §7.7, L8): EV of every legal action, in chips.
     *
     *   fold          0 (chips already in are sunk)
     *   check         R * eq * pot
     *   call          R * eq * (pot + call) - call; R = 1 when all-in; excess
     *                 beyond what a short call can win goes to a side pot
     *   bet / raise   P(all fold) * pot + sum over each set S of likely callers of
     *                   P(S) * (R * eq_vs_S * pot_S - what hero can lose to S)
     *                 with fold rates one standard error on the cautious side, a player who
     *                 already bet or raised this street folding at its own low rate, and a
     *                 chance of being raised back (hero then gives up a weak hand).
     *                 The older single-caller formula stays behind MODEL.multiway = false.
     *
     * R (realization) is a placeholder table by street and position until the
     * simulator fits it (awaiting real data).
     *
     * Fold rates come from the player's shrunk stats (priors.js), so a thin read
     * moves the answer only a little; the pool-only answer is shown beside it
     * when the two differ.
     */










    const R_TABLE = {
        preflop: [0.72, 0.85],
        flop: [0.85, 0.95],
        turn: [0.9, 0.97],
        river: [1, 1],
    };
    /* Fitted in the simulator (tools/fit-realization.mjs) when present; the placeholders otherwise. */
    const realization = (street, inPosition) => {
        const fit = MODEL.fittedR && tables().realization;
        return (fit ? fit.R : R_TABLE)[street][inPosition ? 1 : 0];
    };

    /*
     * Preflop realization by hand class, relative to the table above. Ordering from solver spot studies (GTO Wizard,
     * PokerStrategy) and the deepfold class table; magnitudes are priors until the LAB fits them.
     */
    function classMultiplier(hero) {
        const [a, b] = hero.map((c) => c >> 2).sort((x, y) => y - x);
        const suited = (hero[0] & 3) === (hero[1] & 3);
        if (a === b) return 1.08;
        if (suited && a === 12) return 1.06;
        if (suited && a - b <= 2 && a <= 9) return 1.08;
        if (suited && b >= 8) return 1.04;
        if (suited) return 0.98;
        if (b >= 8) return 0.95;
        return 0.85;
    }

    /* Realization slides to 1 as the stack-to-pot ratio falls: at SPR 0 nothing is left to play, the same as an all-in. */
    const bySpr = (R, spr) => 1 - (1 - R) * Math.min(1, Math.max(0, spr) / 4);

    /*
     * Hero's realized share of the pot. Heads-up the two shares must add to 1 (R_IP*eq_IP + R_OOP*eq_OOP = 1); a bare R*eq
     * made ~20% of every pot that was not all-in vanish, which priced calls below shoves.
     */
    function share(eq, rHero, rOpp) {
        if (!MODEL.potShare) return rHero * eq;
        const h = rHero * eq;
        const o = rOpp * (1 - eq);
        return h + o > 0 ? h / (h + o) : eq;
    }

    /*
     * Fold vs size within a bucket, and by street and heads-up/multiway (lab/foldcurve.py, PHH shape):
     * logit f = logit(bucket rate) + slope * ln(size / bucket centre) + that cell's shift at the centre.
     */
    function sizeCurve(rate, bucket, frac, street, live) {
        const c = tables().foldcurve;
        if (!MODEL.foldCurve || !c || !c.centres || !c.centres[bucket]) return rate;
        const cell = `${street}.${live <= 2 ? 'hu' : 'mw'}`;
        const slope = MODEL.foldCells ? c.slopes[cell] ?? c.slope : c.slope;
        const centre = c.centres[bucket];
        const shift = MODEL.foldCells ? (c.offsets[cell] ?? 0) + (slope - c.slope) * Math.log(centre) : 0;
        const r = clamp(rate, 1e-3, 1 - 1e-3);
        const z = Math.log(r / (1 - r)) + slope * Math.log(Math.max(0.05, frac) / centre) + shift;
        return 1 / (1 + Math.exp(-z));
    }

    const logit = (x) => Math.log(x / (1 - x));
    const logistic = (z) => 1 / (1 + Math.exp(-z));

    /** A fold estimate and the evidence behind it: { f, n, k } (n own opportunities, k prior strength). */
    function foldRate(opp, ctx, street, frac, stakeBB) {
        const p = opp.player || null;
        const est = (key, add = 0) => {
            const e = shrunk(p, key, stakeBB);
            return { f: clamp(e.rate + add, 0.01, 0.97), n: e.n, k: e.k };
        };
        if (street === 'preflop') {
            if (ctx.preflopRaises === 0) return est((opp.limped ? 'fiso.' : 'fvo.') + preBucket(ctx.toBB));
            if (!MODEL.preflopSize) {
                if (ctx.preflopRaises === 1) return opp.isOpener ? est('f3b') : est('fvo.s4', 0.1);
                return { f: 0.5, n: 0, k: 10 };
            }
            /* Facing hero's re-raise: the opener at its fold-to-3-bet, players who already called at their
               fold-to-a-raise-after-limping rate, the rest at fold-vs-open; bigger re-raises fold more. */
            let e;
            if (ctx.preflopRaises >= 2) e = { f: 0.5, n: 0, k: 10 };
            else if (opp.isOpener) e = est('f3b');
            else if (opp.calledPre) e = est('fiso.' + preBucket(ctx.toBB));
            else e = est('fvo.' + preBucket(ctx.toBB), 0.1);
            const slope = 0.5 * Math.log(Math.max(0.3, ctx.to / Math.max(1, 3 * ctx.currentBet)));
            return { ...e, f: clamp(logistic(logit(e.f) + slope), 0.02, 0.95) };
        }
        if (MODEL.raiserFold && opp.aggressive) return est('fraise');
        /* Hero raising a bet: a player with no chips in this street folds far more than to a bet (Torn 15/23). */
        if (MODEL.fcold && ctx.facing > 0 && !(opp.streetContrib > 0)) return est('fcold');
        const bucket = betBucket(frac);
        const e = est('fbet.' + bucket);
        if (!MODEL.raiserFold) {
            const base = sizeCurve(e.f, bucket, frac, street, ctx.live);
            return { ...e, f: ctx.facing > 0 ? clamp(base + 0.12, 0, 0.92) : base };
        }
        /* Past the largest bucket's centre the curve is extrapolation: only a player's own overbet folds may take it further. */
        const c = tables().foldcurve;
        const cap = e.n >= 10 || !c || !c.centres ? frac : Math.min(frac, c.centres.b4);
        return { ...e, f: sizeCurve(e.f, bucket, cap, street, ctx.live) };
    }

    /* One standard error below the estimate, on the logit scale (Beta posterior with k pseudo-opportunities). */
    function cautious(x) {
        if (!MODEL.evLowerBound) return x.f;
        const f = clamp(x.f, 1e-3, 1 - 1e-3);
        const se = Math.sqrt((f * (1 - f)) / (x.n + x.k + 1));
        return logistic(logit(f) - se / (f * (1 - f)));
    }

    /*
     * EV of a bet or raise when some opponents may continue. The three likeliest continuers are priced as
     * every subset of callers (equity against their continuing ranges, the pot they build, what hero can lose
     * against shorter stacks); a fourth or later continuer is priced as the likeliest one of them.
     */
    /* Chance a post-flop bet is raised back, by size and callers (Torn: bets of a third of the pot or less were raised 11/26). */
    function raiseBackRate(frac, callers) {
        const mw = callers >= 2;
        if (frac <= 0.4) return mw ? 0.4 : 0.25;
        if (frac <= 0.7) return mw ? 0.3 : 0.18;
        return mw ? 0.2 : 0.12;
    }

    function continuationEv({ s, opps, fold, foldMean, to, added, dead, R, samples, seed, heroAllIn, realize, frac }) {
        /* Callers of hero's bet are part top slice, part whatever they came in with (8/22 shown Torn callers sat in the bottom 10%). */
        /* Not for shoves and overbets: whoever calls the stack is not the loose caller of a pot-sized bet. */
        const mix = MODEL.callMix && s.street !== 'preflop' && s.toCall === 0 && !heroAllIn && (frac ?? 0.6) <= 1.1 ? (tables().priors.stats.callmix?.mean ?? 0.4) : 0;
        const strong = strongForWar(s.hero, s.board);
        const order = opps.map((_, i) => i).sort((x, y) => fold[x] - fold[y]);
        const top = order.slice(0, 3);
        const rest = order.slice(3);
        const restFold = rest.reduce((m, i) => m * fold[i], 1);
        const branches = [];
        for (let mask = 0; mask < 1 << top.length; mask++) {
            let prob = 1;
            const who = [];
            top.forEach((i, bit) => {
                if (mask & (1 << bit)) {
                    prob *= 1 - fold[i];
                    who.push(i);
                } else {
                    prob *= fold[i];
                }
            });
            if (who.length) {
                branches.push({ prob, who });
            } else {
                branches.push({ prob: prob * restFold, who: [] });
                if (rest.length && restFold < 1) branches.push({ prob: prob * (1 - restFold), who: [rest[0]] });
            }
        }
        let ev = 0;
        let pAllFold = 0;
        let eqW = 0;
        let wCont = 0;
        let varSum = 0;
        for (const br of branches) {
            if (br.prob <= 0) continue;
            if (!br.who.length) {
                pAllFold += br.prob;
                ev += br.prob * s.pot;
                continue;
            }
            if (br.prob < 0.01) {
                /* Too unlikely to be worth an equity run: priced as losing the bet. */
                ev -= br.prob * added;
                continue;
            }
            const ranges = br.who.map((i) => continuingRange(opps[i].range, s.board, dead, foldMean[i], mix));
            const eq = heroEquity(s.hero, s.board, ranges, Math.max(1500, samples >> 3), seed + br.who.reduce((h, i) => h * 7 + i + 1, 1));
            const calls = br.who.map((i) => Math.max(0, Math.min(to - opps[i].streetContrib, opps[i].stack)));
            const cover = Math.max(...br.who.map((i) => opps[i].streetContrib + opps[i].stack));
            const risk = Math.max(0, Math.min(added, cover - s.heroStreet));
            const pot = s.pot + risk + calls.reduce((x, y) => x + y, 0);
            const allIn = heroAllIn || br.who.every((i, j) => calls[j] >= opps[i].stack);
            const sh = realize ? realize(eq.eq, s.heroStack - added, Math.max(...br.who.map((i, j) => opps[i].stack - calls[j])), pot, allIn) : (allIn ? 1 : R) * eq.eq;
            let value = sh * pot - risk;
            const canRaise = br.who.some((i, j) => opps[i].stack > calls[j]);
            if (MODEL.raiseBack && !allIn && canRaise && MODEL.sizeRaiseBack && s.street !== 'preflop') {
                /* Raises here are value: unless hero beats value (a set or better), a raise-back costs the bet. */
                if (!strong) {
                    const rb = raiseBackRate(frac ?? 0.6, br.who.length);
                    value = (1 - rb) * value - rb * risk;
                }
            } else if (MODEL.raiseBack && !allIn && eq.eq < 0.4) {
                /* Someone with chips behind may raise; with little equity hero then gives up the bet. */
                const raiseBack = 1 - br.who.reduce((m, i, j) => m * (opps[i].stack > calls[j] ? 0.9 : 1), 1);
                value = (1 - raiseBack) * value - raiseBack * risk;
            }
            ev += br.prob * value;
            eqW += br.prob * eq.eq;
            wCont += br.prob;
            varSum += (br.prob * (eq.eq > 0 ? sh / eq.eq : 1) * pot * eq.se) ** 2;
        }
        return { ev, pAllFold, eqCont: wCont > 0 ? eqW / wCont : 0, se: Math.sqrt(varSum), whenCalled: pAllFold < 1 ? (ev - pAllFold * s.pot) / (1 - pAllFold) : 0 };
    }

    /* Beats a Torn raiser's value range: QQ+/AK preflop; post-flop a set or better that hero's cards make (not the board's). */
    function strongForWar(hero, board) {
        const r = hero.map((c) => c >> 2).sort((a, b) => b - a);
        if (!board.length) return (r[0] === r[1] && r[0] >= 10) || (r[0] === 12 && r[1] === 11);
        const cat = categoryOf(evaluate([...hero, ...board]));
        return cat >= 3 && cat > categoryOf(evaluate(board));
    }

    function heroEquity(hero, board, ranges, samples, seed) {
        return computeEquity({ hero, board, ranges, samples, seed });
    }

    function candidateTargets(s) {
        const { pot, toCall, heroStreet, heroStack, currentBet, minRaiseTo, bb, street, preflopRaises, limpers } = s;
        const maxTo = heroStreet + heroStack;
        const out = new Set();
        if (street === 'preflop' && preflopRaises === 0) {
            for (const x of [2.5, 3, 4]) out.add(Math.round((x + limpers) * bb));
        } else if (street === 'preflop') {
            for (const x of [3, 4]) out.add(Math.round(currentBet * x));
        } else if (toCall === 0) {
            for (const f of [0.33, 0.5, 0.66, 1]) out.add(Math.round(heroStreet + pot * f));
        } else {
            for (const f of [0.5, 0.75, 1]) out.add(Math.round(currentBet + (pot + toCall) * f));
        }
        const lo = Math.max(minRaiseTo || 0, currentBet + Math.max(bb, s.lastIncrement || 0));
        const list = [...out].map((t) => clamp(t, lo, maxTo)).filter((t) => t > currentBet && t < maxTo);
        /* Safety rail: all-in is only priced where it is normal play, until real fold-to-size data exists:
           short stacks, facing a 3-bet or a shove, or a low stack-to-pot ratio after the flop. */
        const stackBB = (heroStreet + heroStack) / Math.max(1, bb);
        const facingAllIn = s.opponentsAllIn;
        const allInOk = stackBB <= 25 || facingAllIn || (street === 'preflop' ? preflopRaises >= 2 : heroStack <= 3 * Math.max(1, pot));
        if (allInOk || !list.length) list.push(maxTo);
        return [...new Set(list)].sort((a, b) => a - b);
    }

    /**
     * @param s {{
     *   hero: number[], board: number[], street: string, pot: number, toCall: number,
     *   heroStreet: number, heroStack: number, currentBet: number, lastIncrement?: number, minRaiseTo?: number, bb: number,
     *   preflopRaises: number, limpers: number, inPosition: boolean, stakeBB?: number,
     *   opponents: { name: string, stack: number, streetContrib: number, range: Float32Array,
     *                player?: object, isOpener?: boolean, limped?: boolean, isAggressor?: boolean }[],
     *   samples?: number, seed?: number, poolOnly?: boolean
     * }}
     */
    function recommend(s) {
        const samples = s.samples ?? 10000;
        const seed = s.seed ?? 1;
        const opps = s.opponents.filter(Boolean);
        const dead = [...s.hero, ...s.board];
        const R = realization(s.street, s.inPosition);
        const stakeBB = s.stakeBB || s.bb;
        const playerOf = (o) => (s.poolOnly ? null : o.player || null);

        const eqNow = heroEquity(s.hero, s.board, opps.map((o) => o.range), samples, seed);
        const actions = [];
        const callAmt = Math.min(s.toCall, s.heroStack);

        /* Hero's realized share of a pot, given the chips left behind (all-in: plain equity). */
        const rHero = R * (MODEL.classR && s.street === 'preflop' ? classMultiplier(s.hero) : 1);
        const rOpp = realization(s.street, !s.inPosition);
        const maxOpp = Math.max(0, ...opps.map((o) => o.stack));
        const realize = (eq, heroBehind, oppBehind, potAfter, allIn) => {
            if (allIn) return eq;
            const spr = Math.min(heroBehind, oppBehind) / Math.max(1, potAfter);
            return MODEL.potShare ? share(eq, bySpr(rHero, spr), bySpr(rOpp, spr)) : rHero * eq;
        };
        const scale = (eq, sh) => (eq > 0 ? sh / eq : 1);

        /* Folding when checking is free is never right, so fold is only offered facing a bet. */
        if (s.toCall > 0) actions.push({ id: 'fold', label: 'Fold', to: null, ev: 0, se: 0 });
        if (s.toCall <= 0) {
            const sh = realize(eqNow.eq, s.heroStack, maxOpp, s.pot, s.heroStack <= 0);
            actions.push({ id: 'check', label: 'Check', to: null, ev: sh * s.pot, se: scale(eqNow.eq, sh) * s.pot * eqNow.se });
        } else {
            /* A short call cannot win what others put in beyond hero's matched amount. */
            const matched = s.heroStreet + callAmt;
            let excess = 0;
            for (const o of opps) excess += Math.max(0, o.streetContrib - matched);
            const winnable = s.pot - excess + callAmt;
            const allIn = callAmt >= s.heroStack || opps.every((o) => o.stack <= 0);
            const heroBehind = s.heroStack - callAmt;
            const sh = realize(eqNow.eq, heroBehind, maxOpp, winnable, allIn);
            let ev = sh * winnable - callAmt;
            /*
             * Implied odds for a pocket pair calling a raise deep: it flops a set 11.8% of the time and Torn pays sets off
             * (two pair or better won a median 183 bb in raised pots, n = 8). Credited conservatively: a tenth of up to 100 bb.
             */
            const [ra, rb] = s.hero.map((c) => c >> 2);
            const effBehind = Math.min(heroBehind, maxOpp);
            if (MODEL.impliedOdds && s.street === 'preflop' && ra === rb && s.preflopRaises >= 1 && !allIn
                && effBehind >= 100 * s.bb && effBehind >= 6 * winnable) {
                ev += 0.118 * 0.1 * Math.min(effBehind, 100 * s.bb);
            }
            actions.push({ id: 'call', label: 'Call', to: matched, amount: callAmt, ev, se: scale(eqNow.eq, sh) * winnable * eqNow.se, allIn });
        }

        /*
         * Raise wars cost 26.6M of the 20M lost in two live sessions (5 hands): re-raising a raiser, then the stack. Torn
         * raises are value, so re-raise only with hands that beat value, or short enough that shoving is normal play.
         */
        const stackBBAll = (s.heroStreet + s.heroStack) / Math.max(1, s.bb);
        const war = s.street === 'preflop' ? s.preflopRaises >= 2 : !!s.facingRaise;
        const warBlocked = MODEL.warGuard && war && stackBBAll > 25 && !strongForWar(s.hero, s.board);

        if (s.heroStack > callAmt && !warBlocked) {
            const main = [...opps].sort((a, b) => (b.isAggressor ? 1 : 0) - (a.isAggressor ? 1 : 0) || b.stack - a.stack)[0];
            const opponentsAllIn = opps.some((o) => o.stack <= 0);
            for (const to of candidateTargets({ ...s, opponentsAllIn })) {
                const added = to - s.heroStreet;
                const frac = (to - s.currentBet) / Math.max(1, s.pot + s.toCall);
                const ctx = { preflopRaises: s.preflopRaises, facing: s.toCall, toBB: to / Math.max(1, s.bb), live: opps.length + 1, to, currentBet: s.currentBet };
                const est = opps.map((o) => foldRate({ ...o, player: playerOf(o) }, ctx, s.street, frac, stakeBB));
                const foldMean = est.map((x) => x.f);
                const fold = est.map(cautious);
                const isAllIn = to >= s.heroStreet + s.heroStack;
                let ev;
                let se;
                let pAllFold;
                let eqCont;
                let whenCalled;
                if (MODEL.multiway) {
                    ({ ev, se, pAllFold, eqCont, whenCalled } = continuationEv({ s, opps, fold, foldMean, to, added, dead, R, samples, seed: seed + to, heroAllIn: isAllIn, realize, frac }));
                } else {
                    pAllFold = fold.reduce((m, f) => m * f, 1);
                    const cont = continuingRange(main.range, s.board, dead, foldMean[opps.indexOf(main)]);
                    const eqC = heroEquity(s.hero, s.board, [cont], Math.max(2000, samples >> 2), seed + to);
                    const call = Math.max(0, Math.min(to - main.streetContrib, main.stack));
                    const potIfCalled = s.pot + added + call;
                    const r = isAllIn || call >= main.stack ? 1 : R;
                    ev = pAllFold * s.pot + (1 - pAllFold) * (r * eqC.eq * potIfCalled - added);
                    se = (1 - pAllFold) * r * potIfCalled * eqC.se;
                    eqCont = eqC.eq;
                    whenCalled = r * eqC.eq * potIfCalled - added;
                }
                /* The stack goes in as a bluff only with real equity behind it (live 2026-09-27: K-high shoved into a raise and a call). */
                const stackBB = (s.heroStreet + s.heroStack) / Math.max(1, s.bb);
                if (MODEL.commitRail && isAllIn && stackBB > 25 && !opponentsAllIn && eqCont < 0.3) continue;
                /* Everyone folding at once is rare here (70-110% pot: 12/26, break-even for a pot bluff): no bluffs into two or more. */
                if (MODEL.bluffHU && s.street !== 'preflop' && opps.length >= 2 && !isAllIn && eqCont < 0.25) continue;
                actions.push({
                    id: isAllIn ? 'allin' : (s.toCall > 0 || (s.street === 'preflop' && s.currentBet > 0) ? 'raise' : 'bet') + ':' + to,
                    label: isAllIn ? 'All-in' : s.toCall > 0 || (s.street === 'preflop' && s.currentBet > 0) ? 'Raise to' : 'Bet',
                    /* The breakdown the panel explains in money: everyone folds and hero takes the pot, or the average result when called. */
                    to, amount: added, ev, se, pAllFold, eqCont, allIn: isAllIn, foldWin: s.pot, whenCalled,
                });
            }
        }

        const ranked = [...actions].sort((a, b) => b.ev - a.ev);
        let best = ranked[0];
        let second = ranked[1];
        const within = (a, b) => a.ev - b.ev < 2 * Math.sqrt(a.se ** 2 + b.se ** 2) || a.ev - b.ev < 0.1 * Math.max(1, s.bb);
        const gap = second ? best.ev - second.ev : Infinity;
        let marginal = second ? within(best, second) : false;
        /* A tie that risks a quarter of the stack or more goes to the cheaper action (live 2026-09-27: two stacks went in on +0.7 bb and a tie). */
        let cheaper = false;
        if (MODEL.tieCheaper && /^(raise|bet|allin)/.test(best.id)) {
            const passive = ranked.filter((a) => a.id === 'call' || a.id === 'check' || a.id === 'fold')[0];
            /* A free check that ties a bet also wins: a small stab here gets raised 42% of the time (0f851f21, live 2026-09-27). */
            const big = best.amount > 0.25 * (s.heroStack + s.heroStreet);
            if (passive && (big || passive.id === 'check') && within(best, passive)) {
                second = best;
                best = passive;
                marginal = true;
                cheaper = true;
            }
        }
        const need = s.toCall > 0 ? callAmt / (s.pot + callAmt) : 0;
        const mainOpp = opps.find((o) => o.isAggressor) || opps[0];
        const hands = mainOpp && mainOpp.player ? mainOpp.player.hands : 0;
        const conf = confidenceOf(hands, 10);
        const summary = mainOpp ? rangeSummary(mainOpp.range, dead) : null;

        return {
            best, actions, ranked, marginal, second, need, cheaper, gap,
            equity: eqNow,
            confidence: { value: conf, label: conf >= 0.6 ? 'High' : conf >= 0.3 ? 'Medium' : 'Low', hands },
            range: summary && { fraction: summary.fraction, text: summary.text, who: mainOpp.name },
            reason: reasonText(best, eqNow.eq, callNeedEff(actions, need, R), mainOpp, s),
            realization: R,
        };
    }

    const pctOf = (x) => Math.round(x * 100) + '%';

    /* What a call needs once only R of the equity counts (chips behind); an all-in call keeps all of it. */
    function callNeedEff(actions, need, R) {
        const call = actions.find((a) => a.id === 'call');
        return call && !call.allIn ? Math.min(1, need / R) : need;
    }

    function reasonText(best, eq, need, opp, s) {
        const who = opp ? opp.name : 'the table';
        if (best.id === 'fold') {
            return s.toCall > 0 ? `Your ${pctOf(eq)} equity is below the ${pctOf(need)} you need to call.` : 'Nothing gains here.';
        }
        if (best.id === 'check') return `Checking keeps ${pctOf(eq)} equity for free; no bet size gains more.`;
        if (best.id === 'call') return `Calling needs ${pctOf(need)} and you have about ${pctOf(eq)} against ${who}'s range.`;
        const f = best.pAllFold ?? 0;
        if (best.eqCont >= 0.5) {
            return `Value: when called you still have ${pctOf(best.eqCont)} against the hands that continue. They fold only ${pctOf(f)} here.`;
        }
        return `Fold equity: everyone folds about ${pctOf(f)} of the time at this size, and you keep ${pctOf(best.eqCont)} when called.`;
    }

    /* ===== src/core/advisor.js ===== */
    /*
     * Advisor: keeps every opponent's range up to date through the hand and turns
     * the live hand + page snapshot into a decision (spec §7.5, §7.7).
     *
     * Prices come from the page first: the pot is Torn's "POT:" figure (it
     * includes bets not yet collected, confirmed 2026-09-27) and the amount to
     * call is the Call button's label when present, otherwise the log. When the
     * two disagree the label wins and the advice says so.
     */








    const BOARD_LEN = { preflop: 0, flop: 3, turn: 4, river: 5 };

    /**
     * Heads-up push/fold chart (LAB Nash solve) when stacks are 20 bb or less: the SB first in against
     * the BB, or the BB facing the SB's shove. Shown beside the EV answer, never instead of it.
     */
    function pushFoldHint(hand, snap, heroP, heroLabel, opponents, bb, heroCards) {
        if (hand.street !== 'preflop' || opponents.length !== 1 || !bb) return null;
        const eff = Math.min(snap.hero.stack + heroP.street, opponents[0].stack + opponents[0].streetContrib) / bb;
        if (eff > 20) return null;
        const pf = tables().pushfold;
        const depth = pf.depths.reduce((best, d) => (Math.abs(d - eff) < Math.abs(best - eff) ? d : best), pf.depths[0]);
        const ci = classOfCards(heroCards[0], heroCards[1]);
        const oppAllIn = opponents[0].stack <= 0;
        if ((heroLabel === 'SB' || heroLabel === 'BTN') && hand.preflopRaises === 0) {
            const f = pf.push[String(depth)][ci];
            return { label: `Nash push/fold at ${depth} bb`, action: f >= 50 ? 'push' : 'fold', freq: f };
        }
        if (heroLabel === 'BB' && oppAllIn && hand.preflopRaises === 1) {
            const f = pf.call[String(depth)][ci];
            return { label: `Nash call vs a shove at ${depth} bb`, action: f >= 50 ? 'call' : 'fold', freq: f };
        }
        return null;
    }

    function createAdvisor({ getPlayer = () => null } = {}) {
        let gameId = undefined;
        let ranges = new Map();
        let seen = 0;
        let acted = new Set();

        function reset(id) {
            gameId = id;
            ranges = new Map();
            seen = 0;
            acted = new Set();
        }

        function storeOf(hand, name) {
            const p = hand.players.get(name);
            return getPlayer(playerKey({ xid: p && p.xid, name }));
        }

        function update(hand, a, heroCards) {
            const bb = hand.bb || 1;
            const rate = rateOf(storeOf(hand, a.who), bb);
            const board = hand.board.slice(0, BOARD_LEN[a.street]);
            const dead = [...(heroCards || []), ...board];
            const prior = ranges.get(a.who);
            if (a.type === 'fold') {
                ranges.delete(a.who);
                return;
            }
            if (a.street === 'preflop') {
                let kind = null;
                if (a.type === 'raise' || a.type === 'bet') {
                    if (a.allin) kind = 'shove';
                    else kind = a.preflopRaises === 0 ? 'open' : a.preflopRaises === 1 ? 'threebet' : 'fourbet';
                } else if (a.type === 'call') {
                    kind = a.preflopRaises === 0 ? 'limp' : 'flat';
                } else if (a.type === 'check') {
                    kind = 'check';
                }
                if (!kind) return;
                const depth = a.stackBefore && bb ? depthBucket((a.stackBefore + a.toAmount - a.added) / bb) : 'd4';
                if (prior && acted.has(a.who) && kind === 'flat') {
                    const fr = shrunk(storeOf(hand, a.who), 'fiso.' + preBucket(a.currentBet / bb), bb).rate;
                    ranges.set(a.who, continuingRange(prior, [], dead, fr));
                } else {
                    ranges.set(a.who, preflopRange(kind, rate, { depthKey: depth }));
                }
                acted.add(a.who);
                return;
            }
            const frac = a.type === 'bet' || a.type === 'raise' ? a.sizeFrac : a.facingFrac;
            const base = prior || newRange(1);
            ranges.set(a.who, applyPostflopAction(base, board, dead, a.type, {
                sizeFrac: frac ?? 0.6,
                afq: rate('afq'),
                afqN: shrunk(storeOf(hand, a.who), 'afq', bb).n,
                foldRate: rate('fbet.' + betBucket(frac ?? 0.6)),
            }));
            acted.add(a.who);
        }

        /** Bring ranges up to date with the tracker's hand. */
        let lastHand = null;
        function sync(hand, heroName, heroCards) {
            if (!hand) return;
            if (hand !== lastHand) {
                lastHand = hand;
                reset(hand.gameId || 'partial');
            }
            setTable([...hand.players.keys()].map((name) => storeOf(hand, name)));
            for (; seen < hand.actions.length; seen++) {
                const a = hand.actions[seen];
                if (a.who !== heroName) update(hand, a, heroCards);
            }
        }

        /**
         * @returns {{ advice?: object, blocked?: string[], inputs?: object }}
         */
        function advise(hand, snap, settings = {}) {
            const blocked = [];
            if (!snap || !snap.hero) blocked.push('Your seat is not found yet (sit at a table)');
            if (snap && snap.hero && !snap.heroCards) blocked.push('Your cards are not visible yet');
            if (snap && snap.hero && !snap.heroTurn) blocked.push('Waiting for your turn');
            /* Without the name, hero's own log rows would be priced as an opponent's (debugger review). */
            if (snap && snap.hero && !snap.hero.name) blocked.push('Your Torn name is not known yet: it shows after your first action at this table');
            if (!hand) blocked.push('Waiting for the next hand to start');
            if (blocked.length) return { blocked };

            const heroName = snap.hero.name;
            const heroCards = snap.heroCards;
            sync(hand, heroName, heroCards);
            const heroP = hand.players.get(heroName) || { street: 0, total: 0 };
            /* An all-in run-out has no decision; one was journaled on the river of 56e22a25 (live 2026-09-27). */
            if (heroP.allin) return { blocked: ['You are all-in'] };
            const street = hand.street;
            const board = snap.board.length === BOARD_LEN[street] ? snap.board : hand.board.slice(0, BOARD_LEN[street]);
            const bb = hand.bb || 0;
            if (!bb) return { blocked: ['The big blind for this hand was not seen yet'] };

            const logToCall = Math.max(0, hand.currentBet - heroP.street);
            /* The button is the check, the log is the exact figure: labels round to $0.1k once they reach $1k. */
            const label = snap.units === 'bb' ? null : snap.toCallLabel ?? null;
            const agrees = label !== null && Math.abs(label - logToCall) <= (snap.toCallTol || 0) + 0.5;
            const toCall = label === null || agrees ? logToCall : label;
            const toCallSource = label === null ? 'the log' : agrees ? 'log, checked with Call button' : "Torn's Call button";
            const warnings = [];
            if (label !== null && !agrees) {
                warnings.push(`The Call button says ${label}, the log says ${logToCall}; using the button.`);
            }
            const pot = snap.pot ?? [...hand.players.values()].reduce((s, p) => s + p.total, 0);
            const heroStack = snap.hero.stack ?? null;
            if (heroStack === null) return { blocked: ['Your stack could not be read'] };

            const seatByName = new Map(snap.seats.filter((s) => s.name).map((s) => [s.name, s]));
            const firstRaiser = hand.actions.find((x) => x.street === 'preflop' && (x.type === 'raise' || x.type === 'bet'));
            const limpers = new Set(hand.actions.filter((x) => x.street === 'preflop' && x.type === 'call' && x.preflopRaises === 0).map((x) => x.who));
            const opponents = [];
            for (const [name, p] of hand.players) {
                if (name === heroName || p.folded) continue;
                const seat = seatByName.get(name);
                if (seat && seat.folded) continue;
                const store = storeOf(hand, name);
                opponents.push({
                    name,
                    stack: seat && seat.stack !== null ? seat.stack : Math.max(0, (p.stackStart ?? 0) - p.total),
                    streetContrib: p.street,
                    range: ranges.get(name) || newRange(1),
                    player: store,
                    isOpener: !!firstRaiser && firstRaiser.who === name,
                    limped: limpers.has(name),
                    isAggressor: hand.streetAggressor === name || (street === 'preflop' && hand.aggressor === name),
                    /* Bet or raised on this street: facing hero's raise it folds at its own, low rate. */
                    aggressive: street !== 'preflop' && hand.actions.some((x) => x.street === street && x.who === name && (x.type === 'bet' || x.type === 'raise')),
                    calledPre: hand.actions.some((x) => x.street === 'preflop' && x.who === name && x.type === 'call'),
                    type: archetype(store, bb),
                });
            }
            if (!opponents.length) return { blocked: ['No opponent left in the hand'] };
            if (toCall <= 0 && opponents.every((o) => o.stack <= 0 || hand.players.get(o.name)?.allin)) return { blocked: ['Nothing to decide: everyone else is all-in'] };

            /* Hero joins hand.players only after posting or acting: without this, preflop positions were "?" (review B1). */
            const occupied = snap.seats.filter((s) => !s.empty && (s.self || (s.name && hand.players.has(s.name))) && s.index !== null && s.index !== undefined).map((s) => s.index);
            const sb = hand.posts.find((x) => x.blind === 'sb');
            const bbPost = hand.posts.find((x) => x.blind === 'bb');
            const idx = (name) => seatByName.get(name)?.index;
            const pos = snap.dealer !== null ? positionLabels(occupied, snap.dealer, { sb: sb && idx(sb.who), bb: bbPost && idx(bbPost.who) }) : null;
            const heroLabel = pos ? pos.labels.get(snap.hero.index) : null;
            const main = opponents.find((o) => o.isAggressor) || opponents[0];
            const mainLabel = pos ? pos.labels.get(idx(main.name)) : null;
            const inPosition = heroLabel && mainLabel ? isInPosition(heroLabel, mainLabel, occupied.length) : false;

            const input = {
                hero: heroCards, board, street, pot, toCall, heroStreet: heroP.street, heroStack,
                currentBet: hand.currentBet, lastIncrement: hand.lastIncrement, bb,
                preflopRaises: hand.preflopRaises, limpers: hand.limpers, inPosition,
                facingRaise: street !== 'preflop' && hand.actions.some((x) => x.street === street && x.who !== heroName && x.type === 'raise'),
                opponents, samples: settings.samples || 10000, seed: (hand.actions.length + 1) * 7919,
            };
            const exploit = settings.exploit || 'capped';
            const advice = recommend({ ...input, poolOnly: exploit === 'off' });
            let baseline = null;
            if (exploit === 'capped') {
                const pool = recommend({ ...input, poolOnly: true, samples: Math.min(input.samples, 4000) });
                if (pool.best.id.split(':')[0] !== advice.best.id.split(':')[0]) baseline = pool.best;
            }
            const chart = pushFoldHint(hand, snap, heroP, heroLabel, opponents, bb, heroCards);
            return {
                advice: { ...advice, baseline, chart, warnings, heroLabel, inPosition, positionCertainty: pos ? pos.certainty : 'unknown', toCall, toCallSource, pot, main: main.name, mainType: main.type },
                inputs: { gameId: hand.gameId, i: hand.actions.length, street, toCall, pot, heroStack, board, opponents: opponents.map((o) => ({ name: o.name, type: o.type.type, hands: o.type.hands })) },
            };
        }

        return {
            sync,
            advise,
            rangeOf: (name) => ranges.get(name) || null,
            reset: () => reset(undefined),
        };
    }

    /* ===== src/core/record.js ===== */
    /*
     * Shape check for HandRecords arriving from outside (a .jsonl import). Live hands come from the
     * tracker and are trusted; a file can say anything, so names and ids are checked before they
     * become object keys or reach the stats (SAST 2026-09-27: "__proto__" as an xid polluted objects).
     */
    const NAME = /^[\w.-]{1,32}$/;
    const isObj = (o) => !!o && typeof o === 'object' && !Array.isArray(o);
    const num = (x) => typeof x === 'number' && Number.isFinite(x);
    const numOrNull = (x) => x === null || x === undefined || num(x);
    const BAD_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
    const nameOk = (n) => typeof n === 'string' && NAME.test(n) && !BAD_KEYS.has(n);

    function validHandRecord(o) {
        if (!isObj(o) || o.source !== 'torn' || typeof o.gameId !== 'string' || !/^([0-9a-f]{6,64}|partial-\d+)$/.test(o.gameId)) return false;
        if (!isObj(o.table) || !num(o.table.bb) || o.table.bb < 0) return false;
        if (!Array.isArray(o.seats) || o.seats.length > 10) return false;
        for (const s of o.seats) {
            if (!isObj(s) || !nameOk(s.name)) return false;
            if (s.xid !== null && s.xid !== undefined && !/^\d{1,12}$/.test(String(s.xid))) return false;
        }
        const names = new Set(o.seats.map((s) => s.name));
        if (!Array.isArray(o.actions) || !Array.isArray(o.board) || !Array.isArray(o.posts || [])) return false;
        for (const a of o.actions) if (!isObj(a) || !names.has(a.who) || typeof a.type !== 'string' || typeof a.street !== 'string') return false;
        for (const m of [o.net, o.shown || {}]) {
            if (!isObj(m)) return false;
            for (const k of Object.keys(m)) if (!names.has(k)) return false;
        }
        if (!Object.values(o.net).every(num)) return false;
        if (!Array.isArray(o.winners || []) || !isObj(o.flags || {})) return false;
        const card = (c) => Number.isInteger(c) && c >= 0 && c < 52;
        if (!o.board.every(card) || o.board.length > 5) return false;
        if (o.heroCards !== null && o.heroCards !== undefined && !(Array.isArray(o.heroCards) && o.heroCards.every(card))) return false;
        for (const c of Object.values(o.shown || {})) if (!Array.isArray(c) || !c.every(card)) return false;
        if (!(o.posts || []).every((p) => isObj(p) && names.has(p.who) && num(p.amount))) return false;
        if (!o.actions.every((a) => numOrNull(a.added) && numOrNull(a.toAmount) && numOrNull(a.stackBefore))) return false;
        if (!(o.winners || []).every((w) => isObj(w) && names.has(w.who) && num(w.amount))) return false;
        if (!(o.uncalled || []).every((u) => isObj(u) && names.has(u.who) && num(u.amount))) return false;
        if (!numOrNull(o.t0) || !numOrNull(o.t1)) return false;
        if (o.hero !== null && o.hero !== undefined && !nameOk(o.hero)) return false;
        return true;
    }

    const validAction = (a) => isObj(a) && typeof a.id === 'string' && num(a.ev) && numOrNull(a.to);

    function validDecision(o) {
        if (!isObj(o) || typeof o.id !== 'string' || o.id.length >= 80 || !isObj(o.advice)) return false;
        if (!validAction(o.advice.best) || !Array.isArray(o.advice.actions) || !o.advice.actions.every(validAction)) return false;
        if (o.taken !== null && o.taken !== undefined && !(isObj(o.taken) && typeof o.taken.type === 'string' && numOrNull(o.taken.toAmount))) return false;
        return numOrNull(o.bb) && (o.street === undefined || typeof o.street === 'string');
    }

    /* ===== src/core/results.js ===== */
    /*
     * Results (spec §7.9 results page, §7.10): real and all-in-EV profit with a
     * 95% range, by stake, position and opponent, plus leaks from the decision
     * journal. Never judges a decision by how the hand ended.
     */



    const Z = 1.96;

    function meanSd(xs) {
        const n = xs.length;
        if (!n) return { mean: 0, sd: 0 };
        const mean = xs.reduce((s, x) => s + x, 0) / n;
        const v = n > 1 ? xs.reduce((s, x) => s + (x - mean) ** 2, 0) / (n - 1) : 0;
        return { mean, sd: Math.sqrt(v) };
    }

    const heroOf = (rec, heroNames) => (rec.hero && rec.net && Object.hasOwn(rec.net, rec.hero) ? rec.hero : Object.keys(rec.net || {}).find((n) => heroNames.has(n)));

    function summarize(hands, { heroNames = new Set(), decisions = [], typeOf = () => null, now = Date.now() } = {}) {
        const rows = [];
        let skipped = 0;
        for (const rec of hands) {
            /* A malformed record (an old import) is skipped, not allowed to blank the whole page. */
            try {
                const hero = heroOf(rec, heroNames);
                if (!hero) continue;
                /* Counted, so the money shown never silently leaves out hands the log couldn't balance. */
                if (!rec.flags || rec.flags.partial || !rec.flags.balanced) {
                    skipped++;
                    continue;
                }
                const bb = rec.table && rec.table.bb ? rec.table.bb : 0;
                if (!bb || !Number.isFinite(rec.net[hero])) continue;
                const net = rec.net[hero];
                const ai = rec.aiev && rec.aiev.hero === hero ? rec.aiev.result : allInEv(rec, hero, rec.heroCards);
                const seat = rec.seats.find((s) => s.name === hero);
                rows.push({ rec, hero, bb, net, ev: ai ? ai.ev : net, allIn: !!ai, pos: seat ? seat.position : null, t: rec.t1 || rec.t0 || 0 });
            } catch {
                /* skipped */
            }
        }
        rows.sort((a, b) => a.t - b.t);

        const bbNet = rows.map((r) => r.net / r.bb);
        const bbEv = rows.map((r) => r.ev / r.bb);
        const n = rows.length;
        const a = meanSd(bbNet);
        const e = meanSd(bbEv);
        const total = {
            hands: n,
            net: rows.reduce((s, r) => s + r.net, 0),
            ev: rows.reduce((s, r) => s + r.ev, 0),
            netBb: bbNet.reduce((s, x) => s + x, 0),
            evBb: bbEv.reduce((s, x) => s + x, 0),
            bb100: a.mean * 100,
            ci: n > 1 ? (Z * a.sd * 100) / Math.sqrt(n) : null,
            evBb100: e.mean * 100,
            evCi: n > 1 ? (Z * e.sd * 100) / Math.sqrt(n) : null,
            allIns: rows.filter((r) => r.allIn).length,
        };
        total.luck = total.net - total.ev;
        total.skipped = skipped;
        const dayStart = new Date(now);
        dayStart.setHours(0, 0, 0, 0);
        const todayRows = rows.filter((r) => r.t >= dayStart.getTime());
        total.today = { hands: todayRows.length, net: todayRows.reduce((s, r) => s + r.net, 0), netBb: todayRows.reduce((s, r) => s + r.net / r.bb, 0) };

        const group = (keyFn) => {
            const m = new Map();
            for (const r of rows) {
                const k = keyFn(r);
                if (k === null || k === undefined) continue;
                const g = m.get(k) || { key: k, hands: 0, net: 0, ev: 0, netBb: 0, evBb: 0 };
                g.hands++;
                g.net += r.net;
                g.ev += r.ev;
                g.netBb += r.net / r.bb;
                g.evBb += r.ev / r.bb;
                m.set(k, g);
            }
            return [...m.values()].map((g) => ({ ...g, bb100: (g.netBb / g.hands) * 100, evBb100: (g.evBb / g.hands) * 100 }));
        };
        const byStake = group((r) => r.bb).sort((x, y) => x.key - y.key);
        const ORDER = ['UTG', 'UTG1', 'MP', 'LJ', 'HJ', 'CO', 'BTN', 'SB', 'BB'];
        const byPosition = group((r) => r.pos).sort((x, y) => ORDER.indexOf(x.key) - ORDER.indexOf(y.key));

        /* Opponents: hero's result spread over the players on the other side, by their share (exact heads-up, an estimate multiway). */
        const opp = new Map();
        for (const r of rows) {
            const others = Object.entries(r.rec.net).filter(([name]) => name !== r.hero);
            const side = others.filter(([, v]) => (r.net > 0 ? v < 0 : v > 0));
            const weight = side.reduce((s, [, v]) => s + Math.abs(v), 0);
            for (const [name, v] of side) {
                const share = weight ? Math.abs(v) / weight : 0;
                const g = opp.get(name) || { name, hands: 0, net: 0, ev: 0, netBb: 0, evBb: 0 };
                g.net += r.net * share;
                g.ev += r.ev * share;
                g.netBb += (r.net * share) / r.bb;
                g.evBb += (r.ev * share) / r.bb;
                opp.set(name, g);
            }
            for (const [name] of others) {
                const g = opp.get(name) || { name, hands: 0, net: 0, ev: 0, netBb: 0, evBb: 0 };
                g.hands++;
                opp.set(name, g);
            }
        }
        const byOpponent = [...opp.values()].filter((g) => g.hands >= 5).sort((x, y) => Math.abs(y.net) - Math.abs(x.net)).slice(0, 25)
            .map((g) => ({ ...g, type: typeOf(g.name) }));

        decisions = decisions.filter(validDecision);
        const followed = decisions.filter((d) => d.taken);
        const agree = followed.filter((d) => sameAction(d.advice.best, d.taken)).length;
        const leaks = leaksFrom(followed);

        const recent = rows.slice(-50).reverse().map((r) => ({
            t: r.t, gameId: r.rec.gameId, bb: r.bb, cards: r.rec.heroCards, board: r.rec.board, net: r.net, ev: r.allIn ? r.ev : null,
        }));
        const curve = [];
        let cn = 0;
        let ce = 0;
        for (const r of rows) {
            cn += r.net / r.bb;
            ce += r.ev / r.bb;
            curve.push([cn, ce]);
        }
        return { total, byStake, byPosition, byOpponent, followed: followed.length ? agree / followed.length : null, decisions: followed.length, leaks, recent, curve };
    }

    const actionKind = (id) => String(id || '').split(':')[0];

    function sameAction(best, taken) {
        const a = actionKind(best && best.id);
        const b = taken && taken.type;
        if (a === b) return true;
        if (a === 'allin' && taken && taken.allin) return true;
        if ((a === 'bet' || a === 'raise') && (b === 'bet' || b === 'raise')) return true;
        return false;
    }

    /** Match the action taken to the closest action the engine priced. */
    function pricedTaken(decision) {
        const t = decision.taken;
        const acts = decision.advice.actions || [];
        if (!t) return null;
        if (t.type === 'fold') return acts.find((x) => x.id === 'fold') || null;
        if (t.type === 'check') return acts.find((x) => x.id === 'check') || null;
        if (t.type === 'call') return acts.find((x) => x.id === 'call') || null;
        const sized = acts.filter((x) => x.to);
        if (!sized.length) return null;
        return sized.reduce((best, x) => (Math.abs(x.to - t.toAmount) < Math.abs(best.to - t.toAmount) ? x : best));
    }

    function leaksFrom(decisions) {
        const m = new Map();
        for (const d of decisions) {
            let took;
            try {
                if (sameAction(d.advice.best, d.taken)) continue;
                took = pricedTaken(d);
            } catch {
                continue;
            }
            if (!took) continue;
            const cost = (d.advice.best.ev - took.ev) / (d.bb || 1);
            if (!(cost > 0)) continue;
            const key = `${d.street}: ${d.advice.best.label} advised, you ${d.taken.type}${d.villainType ? ' vs ' + d.villainType : ''}`;
            const g = m.get(key) || { what: key, spots: 0, cost: 0, advice: d.advice.best.label };
            g.spots++;
            g.cost += cost;
            m.set(key, g);
        }
        return [...m.values()].map((g) => ({ ...g, each: g.cost / g.spots })).sort((x, y) => y.cost - x.cost).slice(0, 20);
    }

    /* ===== src/sources/dom/reader.js ===== */
    /*
     * The page reader (spec §7.1, L1). It only reads: querySelector, text,
     * classes, attributes and element rects. It never clicks, focuses, types into
     * or intercepts anything on Torn's page.
     *
     * Confirmed on the live page 2026-09-27 (docs/torn-markup-2026-09-27.md), spectating and
     * seated: seats, stacks, state text, the dealer marker, board aria label, total/round pot,
     * per-seat bets, log rows, the units toggle, hero's seat (playerMeGateway), hero's cards, and
     * the action and queue buttons. Still unconfirmed: what big-blind display mode changes.
     * Anything unsure returns null, so the UI shows "?" instead of guessing.
     */



    const has = (el, frag) => !!el && typeof el.className === 'string' && el.className.includes(frag);
    const q = (root, sel) => (root ? root.querySelector(sel) : null);
    const qa = (root, sel) => (root ? Array.from(root.querySelectorAll(sel)) : []);
    const text = (el) => (el ? el.textContent.replace(/\s+/g, ' ').trim() : '');

    function findTableRoot(doc = document) {
        return q(doc, '[class*="holdemWrapper"]') || q(doc, '[class*="tableWrap"]');
    }

    function seatIndexOf(el) {
        const m = /playerPositioner-(\d)/.exec(el.className || '');
        return m ? Number(m[1]) : null;
    }

    function seatCardsIn(el) {
        const out = [];
        for (const face of qa(el, '[class*="front"] > *, [role="img"]')) {
            const label = face.getAttribute && face.getAttribute('aria-label');
            let c = -1;
            if (label && !/face down/i.test(label)) c = parseCardWords(label);
            if (c < 0) {
                for (const token of String(face.className || '').split(/\s+/)) {
                    c = parseCardClass(token);
                    if (c >= 0) break;
                }
            }
            if (c >= 0 && !out.includes(c)) out.push(c);
        }
        return out;
    }

    function readSeatEl(box, index) {
        const player = /^player-/.test(box.id || '') ? box : q(box, '[id^="player-"]');
        if (!player) return { index, empty: true };
        const xid = (/^player-(\d+)$/.exec(player.id) || [])[1] || null;
        const cls = player.className || '';
        /* Hero's seat (seated capture 2026-09-27) is state > pot "$X" + span "Waiting BB"; no potString, no name. */
        const heroPot = q(player, '[class*="state"] > [class*="pot"]');
        const stateEl = q(player, 'p[class*="state"]') || (heroPot ? q(heroPot.parentElement, ':scope > span') : q(player, '[class*="state"]'));
        const countEl = q(player, '[class*="countDown"]');
        const stackMoney = parseMoney(text(q(player, '[class*="potString"]') || heroPot));
        const hand = q(player, '[class*="hand"]');
        return {
            index,
            xid,
            name: text(q(player, '[class*="name"]')) || null,
            stack: stackMoney ? stackMoney.value : null,
            stackUnit: stackMoney ? stackMoney.unit : null,
            folded: /folded/.test(cls),
            active: /(^|\s)active/.test(cls.replace(/_{1,3}[A-Za-z0-9-]+/g, '')) || !!countEl,
            self: /(^|\s)self/.test(cls.replace(/_{1,3}[A-Za-z0-9-]+/g, '')),
            stateText: countEl ? '' : text(stateEl),
            /* countDown holds two section spans ("14" "20"); the first ticks down once a second. */
            countDown: countEl ? Number(text(q(countEl, 'span') || countEl).split(' ')[0]) || null : null,
            cards: hand ? seatCardsIn(hand) : [],
            rect: player.getBoundingClientRect ? player.getBoundingClientRect() : null,
            el: player,
        };
    }

    function readSeats(root) {
        const seats = [];
        for (const box of qa(root, '[class*="playerPositioner"]')) {
            const index = seatIndexOf(box);
            if (index === null) continue;
            seats.push(readSeatEl(box, index));
        }
        /*
         * Seated, hero sits in playerMeGateway outside the positioners, which then run 1-8 clockwise
         * from hero (live 2026-09-27: dealer position-2, SB 3, BB 4). So hero is ring index 0.
         */
        const self = qa(root, '[id^="player-"]').find((p) => /(^|\s)self/.test((p.className || '').replace(/_{1,3}[A-Za-z0-9-]+/g, '')));
        if (self && !seats.some((s) => s.el === self)) {
            const zeroTaken = seats.some((s) => s.index === 0 && !s.empty);
            if (!zeroTaken) seats.splice(0, seats.length, ...seats.filter((s) => s.index !== 0));
            seats.push({ ...readSeatEl(self, zeroTaken ? null : 0), outside: true });
        }
        return seats;
    }

    /** Seated and playing: a self seat exists and is not sitting out. Read before the gate decides. */
    function heroSeated(root) {
        const self = qa(root, '[id^="player-"]').find((p) => /(^|\s)self/.test((p.className || '').replace(/_{1,3}[A-Za-z0-9-]+/g, '')));
        return !!self && !/sitting out/i.test(text(self));
    }

    function readDealer(root, seats) {
        const d = q(root, '[class*="dealer"]');
        if (!d) return null;
        const m = /position-(\d|self)/.exec(d.className || '');
        if (!m) return null;
        if (m[1] === 'self') {
            const hero = seats.find((s) => s.self);
            return hero ? hero.index : null;
        }
        return Number(m[1]);
    }

    function readBoard(root) {
        const el = q(root, '[class*="communityCards"]');
        const label = el && el.getAttribute('aria-label');
        if (!label) return { cards: [], known: false };
        const body = label.replace(/^community cards,?\s*/i, '');
        if (/face down/i.test(body)) return { cards: [], known: true };
        const cards = body.split(',').map((s) => parseCardWords(s.trim())).filter((c) => c >= 0);
        return { cards, known: true };
    }

    function readPots(root) {
        const total = parseMoney(text(q(root, '[class*="totalPotWrap"]')));
        const round = parseMoney(text(q(root, '[class*="roundPot"]:not([class*="roundPotWrap"])')));
        const bets = {};
        for (const el of qa(root, '[class*="player-pot-"]')) {
            const m = /player-pot-(\d)/.exec(el.className || '');
            const v = parseMoney(text(el));
            if (m && v) bets[m[1]] = v.value;
        }
        return { total: total ? total.value : null, round: round ? round.value : null, unit: total ? total.unit : null, bets };
    }

    /** The units toggle reads "Showing dollars" or (presumably) "Showing big blinds". */
    let unitsButton = null;
    function readUnits(doc = document) {
        const known = unitsButton && unitsButton.isConnected && unitsButton.ownerDocument === doc ? [unitsButton] : null;
        for (const b of known || qa(doc, 'button[aria-label^="Showing" i], button')) {
            const label = (b.getAttribute('aria-label') || b.textContent || '').trim();
            if (/^showing dollars/i.test(label)) {
                unitsButton = b;
                return 'dollars';
            }
            if (/^showing (big blinds|bb)/i.test(label)) {
                unitsButton = b;
                return 'bb';
            }
        }
        return null;
    }

    /** Labels abbreviate ("Call $38.5k", "Call $491.4k"), so an amount is only good to half its last digit. */
    function roundingOf(label) {
        const m = /[\d,]+(?:\.(\d+))?\s*(k|m|b)\b/i.exec(String(label || ''));
        if (!m) return 0;
        const mult = { k: 1e3, m: 1e6, b: 1e9 }[m[2].toLowerCase()];
        return 0.5 * 10 ** -(m[1] ? m[1].length : 0) * mult;
    }

    /**
     * Hero's action buttons, read by their visible label only (seated capture 2026-09-27:
     * "Raise to $72k", "Call $38.5k", "Fold"; "Bet $1k", "Check", "Fold").
     * Never clicked, never listened to. Our own overlay is skipped.
     */
    function readActionLabels(root, overlayHost) {
        const out = [];
        for (const b of qa(root, 'button')) {
            if (overlayHost && overlayHost.contains(b)) continue;
            /* Pre-action queue ("Call Any", "Call $5k", "Fold") is class queueable and shows before hero's turn. */
            if (has(b, 'queueable')) continue;
            const label = (b.textContent || b.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
            if (label.length > 30 || /\/|\bany\b/i.test(label)) continue;
            const m = /^(fold|check|call|bet|raise|all[\s-]?in)\b(.*)$/i.exec(label);
            if (m) out.push({ kind: m[1].toLowerCase().replace(/[\s-]/g, ''), label, amount: parseMoney(m[2]), tol: roundingOf(m[2]) });
        }
        return out;
    }

    /**
     * Where Torn's own controls are (action and queue buttons, size chips, the amount box): one rect
     * around them, so our panel can stay out of the way. Reads rects only.
     */
    function readActionArea(root) {
        let box = null;
        for (const e of qa(root, 'button[class*="btn"], button[class*="option"], button[class*="controlBtn"], input[class*="input-money"]')) {
            const r = e.getBoundingClientRect ? e.getBoundingClientRect() : null;
            if (!r || !r.width || !r.height) continue;
            box = box
                ? { left: Math.min(box.left, r.left), top: Math.min(box.top, r.top), right: Math.max(box.right, r.right), bottom: Math.max(box.bottom, r.bottom) }
                : { left: r.left, top: r.top, right: r.right, bottom: r.bottom };
        }
        return box;
    }

    /** Log rows as { key, state, won, actor, text }; key has amounts blanked (a $/BB switch rewrites them). */
    function readLogRows(doc = document) {
        const list = q(doc, '[class*="messagesList"]') || q(doc, '[aria-label="Game log"]');
        /* Placeholders Torn swaps out ("X is thinking…", "Your turn…") are not log lines (live 2026-09-27). */
        const placeholder = (li) => /is thinking|^\s*your turn/i.test(li.textContent || '');
        return qa(list, 'li').filter((li) => !placeholder(li)).map((li) => {
            const cls = li.className || '';
            const actor = text(q(li, 'em'));
            const t = text(q(li, 'span'));
            /* Hero's own rows carry an extra `current` class (seated capture 2026-09-27). */
            return { state: /state/.test(cls), won: /won/.test(cls), current: /(^|\s)current/.test(cls.replace(/_{1,3}[A-Za-z0-9-]+/g, '')), actor, text: t, key: actor + '|' + t.replace(/[\d,.]+/g, '#') };
        });
    }

    /**
     * Hero's seat has no name element; the log uses the Torn name. Torn's own #torn-user input holds
     * { id, playername }. Trusted only when its id is the self seat's XID.
     */
    function heroNameFor(hero, doc = document) {
        const el = doc.getElementById ? doc.getElementById('torn-user') : null;
        if (!el || !hero || !hero.xid) return null;
        try {
            const u = JSON.parse(el.value || '');
            return u && String(u.id) === hero.xid && typeof u.playername === 'string' && u.playername ? u.playername : null;
        } catch {
            return null;
        }
    }

    function readTable(root,{ overlayHost = null, doc = document } = {}) {
        const seats = readSeats(root);
        const board = readBoard(root);
        const pots = readPots(root);
        const actions = readActionLabels(root, overlayHost);
        const hero = seats.find((s) => s.self) || null;
        if (hero && !hero.name) hero.name = heroNameFor(hero, doc);
        return {
            seats,
            dealer: readDealer(root, seats),
            board: board.cards,
            boardKnown: board.known,
            pot: pots.total,
            roundPot: pots.round,
            potUnit: pots.unit,
            bets: pots.bets,
            units: readUnits(doc),
            hero,
            heroCards: hero && hero.cards.length === 2 ? hero.cards : null,
            actions,
            toCallLabel: (actions.find((a) => a.kind === 'call') || {}).amount?.value ?? null,
            toCallTol: (actions.find((a) => a.kind === 'call') || {}).tol ?? 0,
            heroTurn: !!hero && (hero.active || actions.length > 0),
        };
    }

    /* ===== src/sources/log/logdiff.js ===== */
    /*
     * Snapshot diff of the game log (spec §7.1; WWpokerHUD's lesson): Torn
     * re-renders the list in place, so mutation records replay history. Instead
     * compare the whole list of row keys with the previous one: the new rows
     * are whatever follows the longest overlap between the old tail and the
     * new list.
     */

    /** Index in `cur` where new rows start, given the previous keys. */
    function newRowsStart(prev, cur) {
        /* An empty previous list (a fresh table) means every row is new. */
        if (!prev.length) return 0;
        const maxK = Math.min(prev.length, cur.length);
        for (let k = maxK; k > 0; k--) {
            let ok = true;
            for (let i = 0; i < k; i++) {
                if (prev[prev.length - k + i] !== cur[i]) {
                    ok = false;
                    break;
                }
            }
            if (ok) return k;
        }
        return 0;
    }

    function createLogDiff() {
        let prev = null;
        return {
            /**
             * First call primes: older history is not parsed, but the hand in progress is, from its
             * "Game … started" row on. Otherwise sitting down (or resuming after a pause) mid-hand lost
             * the blinds, and the advisor stayed blocked until the next hand (live report 2026-09-27).
             * Returns the rows added since the last call.
             */
            next(rows) {
                const keys = rows.map((r) => r.key);
                if (prev === null) {
                    prev = keys;
                    for (let i = rows.length - 1; i >= 0; i--) {
                        if (/^game$/i.test(rows[i].actor || '') && /\bstarted\b/i.test(rows[i].text || '')) return rows.slice(i);
                    }
                    return [];
                }
                let start = newRowsStart(prev, keys);
                /*
                 * Torn shows a placeholder last row ("X is thinking…", "Your turn…") and then replaces it.
                 * If the overlap broke, retry without our last row or two before treating it all as new.
                 */
                for (let drop = 1; start === 0 && drop <= 2 && prev.length > drop; drop++) start = newRowsStart(prev.slice(0, -drop), keys);
                prev = keys;
                return rows.slice(start);
            },
            reset() {
                prev = null;
            },
        };
    }

